programs.sol:
"""Approximate a document-initial signal with broad token categories.

Use a mostly negative category average at the first token, continuing while
all tokens seen in the document are identical. Words are strongest; digits,
punctuation and whitespace are weaker. End markers and bullets are exceptions.

After the initial run, predict zero except for literal escaped newlines,
backticks near nonbreaking spaces, and small nonbreaking-space adjustments.
Fine lexical and contextual differences in strength are deliberately omitted.
"""
import math
import regex

READS = ()

LINKING_WORDS = set(
    'of in on at for to by from with as or and but if is are was be'.split()
)

def initial(s):
    if s == '<|endoftext|>':
        return 5.3
    if s.startswith('<|'):
        return -13.1
    if '\n' in s or '\r' in s:
        return 0.0
    w = s.strip()
    if not w:
        return -6.0 if '\t' in s else -1.0 - 1.8 * math.log(max(1, len(s)))
    if w.isdigit():
        return -3.7
    if '\ufffd' in w and not any(c.isalpha() for c in w):
        return -8.0
    if not any(c.isalpha() for c in w):
        if w == '•':
            return 2.7
        if len(set(w)) == 1 and (len(w) >= 4 or w[0] == '·'):
            return -6.7
        if all(c in '.,;:。！？，：；!?' for c in w):
            return -2.0
        return -4.5
    if regex.search(
        r'\p{Script=Han}|\p{Script=Hiragana}|\p{Script=Katakana}', w
    ):
        return -8.2
    if w.lower() in LINKING_WORDS:
        return -8.2
    return -12.9 if s.startswith(' ') else -10.6


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
    repeating = first or (carry[2] and prefix.token_ids[-1] == carry[3])
    if repeating:
        value = initial(s)
    elif '\\n' in s or (s == 'n' and tail.endswith('\\')):
        value = 1.1
    elif '`' in s and s.count('`') == 1 and '\xa0' in tail:
        value = 1.7
    elif s and all(c == '\xa0' for c in s):
        value = 0.25 if len(s) == 1 else -0.08 * len(s)
    else:
        value = 0.0
    return (doc, (tail + s)[-80:], repeating, prefix.token_ids[-1]), value

"""Approximate a feature for short European word beginnings and elisions.

Predict negative pulses on n-/ne- and Slavic pr-/př-/prz- fragments,
including a few first syllables split over tokens. French n/ne is especially
strong after subject pronouns. Language is estimated from recent complete
words, not from future letters. French clitic apostrophes have a separate
negative pulse; nonbreaking spaces and middle dots have small positive ones.
Most tokens predict zero. This leaves finer context effects unexplained.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = (
    'en', 'fr', 'cs', 'sk', 'pl', 'es', 'it', 'pt', 'de', 'vi', 'nl', 'ru', 'bg',
)
SUBJECTS = set('je tu il elle on nous vous ils elles ce cela ceci qui'.split())
LATIN_SLAVIC = ('cs', 'sk', 'pl')


@lru_cache(maxsize=24000)
def word_scores(word):
    return tuple(max(0.0, zipf_frequency(word, lang) - 2.5)
                 for lang in LANGUAGES)


def language(text):
    # Ignore single-letter variables: they do not identify a prose language.
    words = [w for w in re.findall(r'[^\W\d_]+', text.lower()) if len(w) > 1]
    scores = [0.0] * len(LANGUAGES)
    for word in words[-35:]:
        for i, value in enumerate(word_scores(word)):
            scores[i] += value
    best = max(range(len(scores)), key=scores.__getitem__)
    if scores[best] < max(3.0, 0.8 * min(35, len(words))):
        return 'unknown'
    return LANGUAGES[best]


def response(token, tail):
    match = re.search(r'[^\W\d_]+$', tail)
    previous = match.group() if match else ''
    low = previous.lower()
    piece = token.strip()
    p = piece.lower()
    capital = piece[:1].isupper()
    initial = token[:1].isspace() or not previous
    # In particular, the n in a literal backslash-n is not a word beginning.
    spaced = token[:1].isspace() or not tail or tail[-1].isspace()

    if spaced and p in (
        'n', 'ne', 'no', 'non', 'nie', 'nich', 'nad', 'nep', 'ned', 'nied',
    ):
        lang = language(tail)
        if lang == 'fr' and p in ('n', 'ne'):
            if capital and p == 'n':
                return -0.9
            if low in SUBJECTS:
                return -8.2 if low == 'qui' else -9.6
            return -7.2 if p == 'ne' else -5.5
        if lang in LATIN_SLAVIC and p not in ('no', 'non'):
            return -0.7 if capital else -2.7
        if (lang == 'es' and p == 'no') or (lang == 'it' and p == 'non'):
            return -1.5
        return 0.0

    if initial and p in ('н', 'не', 'ни', 'нед', 'пер'):
        if capital and p in ('н', 'ни'):
            return -1.2
        if capital and p == 'не':
            return -1.7
        return {'н': -3.2, 'не': -1.15, 'ни': -2.4,
                'нед': -2.2, 'пер': -1.8}[p]
    if initial and p == 'não':
        return -1.25
    if initial and p in ('пр', 'př', 'prz', 'pr', 'pred', 'sv'):
        if p in ('pr', 'pred', 'sv'):
            strength = -2.7 if p == 'sv' else -2.0
            return strength if language(tail) in LATIN_SLAVIC else 0.0
        if p == 'пр':
            if language(tail) == 'bg' or not token[:1].isspace():
                return -2.4
        if p == 'prz':
            return -4.2
        return -2.2 if capital else -5.5

    # Completing a consonant cluster can also produce the pulse.
    if not initial and low + p in ('prz', 'naprz', 'nieprz'):
        return -4.8
    if not initial and p in ('р', 'ř'):
        czech = p == 'ř'
        if low.endswith(('п', 'p')):
            if low.startswith(('не', 'ne')):
                return -9.0
            if low.startswith(('на', 'na')):
                return -8.0 if czech else -4.8
            return -7.8 if czech else -3.4
        if low and low[-1] in 'бвкдстbvkdst' and len(low) <= 3:
            return -3.2 if czech else -1.1
        if czech and low in ('po', 'pot', 'pat'):
            return -2.3
        return -0.1
    if not initial and piece.isalpha():
        if low == 'n' and p in ('ě', 'á', 'í'):
            return -2.8
        if low + p in ('нав', 'нис'):
            return -1.7
        if low + p == 'прев':
            return -1.1
        if low + p in (
            'прив', 'нив', 'неп', 'нез', 'pří', 'napří', 'nepří', 'přív',
        ):
            return -2.7 if previous[:1].isupper() else -3.3
        base = low[2:] if low.startswith('не') else low
        if p == 'н' and base and len(base) <= 3 and base[-1:] in 'бвкдст':
            return -4.9 if base != low else -2.9

    if piece in ("'", '’') and not initial:
        if low in ('n', 's', 'm', 't', 'j', 'qu'):
            if language(tail[:-len(previous)]) != 'fr':
                return -0.3
            return -7.4 if low == 'n' else -2.7
        if low == 'd':
            return -1.7
        if low == 'l':
            return -0.5
    if token == '\xa0':
        return 0.35
    if piece and set(piece) == {'·'}:
        return 0.44 * len(piece)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, (tail + token)[-256:]), float(response(token, tail))

"""Chinese verbs of permission, prompting, prevention, and desire.

English dictionary glosses provide the semantic classes, not a token-id table.
Normally a verb's leading sense is strongest; incidental senses count less.
Recognize
split Chinese words and UTF-8 characters, resetting at document boundaries.
Vietnamese permission, compulsion and help have small explicit rules.
English forms of "allow" and paired middle dots receive negative values.
"""
import codecs
import re
from functools import lru_cache
import cedict
import wordnet
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}+')
LIGHT_VERBS = frozenset('可准让讓给給得要应應该該将將需須须止')
# (whole-word strength, single-character strength, English verb meanings)
FAMILIES = (
    (3.6, 2.4, 'encourage allow permit license authorize prohibit forbid ban'),
    (3.4, 0.5, 'welcome prevent'),
    (2.1, 0.5, 'attract fascinate avert avoid obstruct hinder merit deserve'),
    (1.5, 1.5, 'compel coerce force pressure extort spit vomit'),
    (1.4, 0.4, 'urge exhort incite instigate motivate prompt spur summon appeal'),
    (1.1, 0.3, 'request demand require beseech solicit invite recruit enlist'),
    (1.0, 0.3, 'suggest recommend advise instruct remind warn guide direct'),
    (0.9, 0.3, 'support back promote stimulate provoke facilitate oppose resist'),
    (0.6, 0.3, 'need want hope wish desire dare willing help assist fear dread'),
    (0.6, 0.2, 'influence affect cause disturb restrict limit inhibit suppress'),
    (0.5, 0.3, 'like love dislike hate admire appreciate thank grateful'),
    (0.1, 1.4, 'breathe suck inhale'),
)
PATTERNS = tuple(
    re.compile(r'\bto (?:be )?(?:' + '|'.join(words.split()) + r')\b')
    for _, _, words in FAMILIES
)

@lru_cache(maxsize=30000)
def meaning(word):
    glosses = cedict.glosses(word)
    if not glosses:
        return 0.0
    useful = [
        g for g in glosses
        if not g.lower().startswith(('surname ', 'variant of ', 'old variant of '))
    ]
    text = ' '.join(useful).lower()
    first = useful[0].lower() if useful else ''
    if first.startswith('to be in favor of'):
        first = 'to support'
    source = first if len(word) == 1 else first + ' ' + text
    verbs = re.search(r'\bto (?:be )?([a-z]+)', source)
    primary = verbs.group(1) if verbs else ''
    best = 0.0
    for (whole, single, words), pattern in zip(FAMILIES, PATTERNS):
        if pattern.search(text):
            strength = 1.0 if primary in words.split() else 0.05
            best = max(best, strength * (single if len(word) == 1 else whole))
    if re.search(r'\bto (prohibit|forbid|ban)\b', text):
        best = max(best, 2.4 if len(word) == 1 else 3.6)
    if 'to summon' in text:
        best = max(best, 2.5)
    if 'to pray for' in text:
        best = max(best, 1.1 if len(word) == 1 else 3.0)
    if primary == 'contribute' and 'to promote' in text:
        best = max(best, 1.6)
    if 'to permit' in text and 'to allow' in text:
        best = max(best, 3.3 if len(word) == 1 else 4.3)
    if 'to request' in text and 'to demand' in text:
        best = max(best, 1.3)
    # Greeting arrivals and prophylaxis are weaker than inviting or stopping.
    if primary == 'welcome' and 'welcome' not in glosses:
        best = min(best, 0.5)
    if word.startswith(('请', '請')) or 'higher-ranking' in text:
        best = min(best, 0.25)
    if 'prophylactic' in text:
        best = min(best, 0.4)
    if word.lstrip('不') in LIGHT_VERBS:
        best = min(best, 0.15)
    return best

@lru_cache(maxsize=30000)
def ending(text):
    for n in range(min(4, len(text)), 0, -1):
        word = text[-n:]
        if cedict.glosses(word):
            return meaning(word)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, pending = '', b''
    else:
        _, tail, pending = carry
    was_split = bool(pending)
    raw = pending + prefix.token_bytes[-1]
    added, used = codecs.utf_8_decode(raw, 'ignore', False)
    pending = raw[used:]
    text = tail + added
    current = HAN.findall(added)
    value = 0.0
    if current:
        word = current[-1]
        value = ending(word)
        if len(word) == 1 and regex.search(r'[\p{Hiragana}\p{Katakana}]', tail):
            value *= 0.3
        # A compound split across tokens still has its ordinary word meaning.
        if HAN.fullmatch(added) and tail and len(text) > len(word):
            for n in range(min(4, len(text)), max(1, len(word)), -1):
                if cedict.glosses(text[-n:]):
                    value = max(value, meaning(text[-n:]))
                    break
    if was_split and added[:1] in ('励', '勵'):
        value = max(value, 4.5)
    # A split encouragement character is already identifiable after 鼓/激/獎.
    if pending and text.endswith(('鼓', '激', '獎', '奖')):
        if any(ch.encode('utf-8').startswith(pending) for ch in '励勵'):
            value = max(value, 2.6)
    if added.strip('·') == '' and len(added) >= 2:
        value = -1.75
    english = added.strip().lower()
    if text.endswith('cho phép'):
        value = 5.5  # Vietnamese: to permit.
    elif english == 'buộc':
        value = 2.1  # Vietnamese: compel/bind.
    elif english in ('được', 'giúp'):
        value = 0.4  # Permission/possibility and help.
    if english.isascii() and english.isalpha():
        if 'allow' in wordnet.base_forms(english):
            value = -0.28
    return (doc, text[-8:], pending), float(value)

"""A sparse phrase detector, not a general semantic classifier.

Positive responses mark collective 'of' phrases, Chinese expressions for
'passing through' and 'having', and three particular adverbs. Negative
responses distinguish programming setters from the ordinary word 'set'.
There is also a document-initial '#pragma' response. The numbers are rounded
training estimates; unrecognized contexts predict zero.
"""

READS = ()

# Response after the collective alone, after "a", and after "the".
COLLECTIVES = {
    'series': (0.42, 1.11, 0.22),
    'set': (0.50, 1.09, 0.14),
    'group': (0.13, 0.48, 0.02),
    'collection': (0.16, 0.35, 0.13),
    'sequence': (0.14, 0.14, 0.14),
    'variety': (0.14, 0.14, 0.14),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, recent = '', '', b''
    else:
        _, previous, before, recent = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    old = previous.strip()
    value = 0.0

    if token == ' of':
        determiner = before.strip().lower()
        column = 1 if determiner == 'a' else 2 if determiner == 'the' else 0
        value = COLLECTIVES.get(old.lower(), (0.0, 0.0, 0.0))[column]
    elif word == 'set' and token != 'set':
        if old == 'void':
            value = -1.29
        elif old in ('function', 'const', 'def'):
            value = {'function': -0.93, 'const': -1.13, 'def': -0.55}[old]
        elif previous.isspace():
            value = -0.75
        elif old == ';':
            value = -1.09
        elif any(c in recent[-80:] for c in (b'{', b'}', b';')):
            value = -0.41
    elif token == 'set':
        value = -0.15
    elif token == '.set':
        value = -0.25
    elif token == ' Set':
        value = -0.6 if old == 'void' else -0.08
    elif token in ('经过', '經過'):
        value = 3.5
    elif token in ('过', '過'):
        if recent.decode('utf-8', errors='ignore').endswith(('经', '經')):
            value = 3.5
    elif token == '由':
        if old in ('经', '經'):
            value = 1.9
        elif old == '藉':
            value = 0.7
    elif token == '具有':
        value = 0.61
    elif token == '最具':
        value = 1.54
    elif token == ' specially':
        value = 1.8
    elif token == 'ably' and old == 'suit':
        value = 0.78
    elif token == 'ly' and old == 'popular':
        value = 1.24
    elif token == '#pragma' and (not previous or previous == '<|endoftext|>'):
        value = 1.69

    recent = (recent + prefix.token_bytes[-1])[-160:]
    return (doc, token, previous, recent), value

"""Approximate an opening-token response and locative prepositions.

At document starts, digits, whitespace, code openers and punctuation get
larger values; pronouns get small negative values. Title/Question headings
are explicit exceptions. Identical repetitions retain the opening response.
Elsewhere, recognize on/at/upon and six translations, reducing the response
in dependency phrases and directed-action phrases such as 'look at'.
Most other tokens get zero. Other word-specific opening effects are omitted.
"""
import re
import unicodedata

CODE_OPENERS = {
    'int', 'float', 'double', 'char', 'void', 'bool', 'struct', 'class',
    'enum', 'namespace', 'package', 'import', 'using', 'def', 'function',
    'public', 'private', 'static', 'try',
}

READS = ()
PRONOUNS = {
    'i', 'we', 'you', 'he', 'she', 'it', 'they',
    'this', 'that', 'these', 'those',
}
DEPENDENCY = re.compile(
    r'\b(bas(?:e|ed|ing)|depend\w*|rel(?:y|ies|ied|ying)|'
    r'focus\w*|effects?|impacts?)\b', re.I
)
TRANSLATIONS = {
    'sur': 0.87, 'på': 0.78, 'na': 0.38,
    'auf': 0.26, 'на': 0.19, 'على': 0.50,
}


def opening(s):
    t = s.strip()
    if '\ufffd' in s:
        return 0.0
    if s.startswith('<|'):
        return -0.55
    if not t:
        return 3.0 if '\n' in s else 8.8
    if t.isascii() and t.isdigit():
        if t == '0':
            return 10.3
        if t == '9':
            return 2.1
        return 7.5
    if t == 'Title':
        return 5.2
    if t == 'Question':
        return 15.6
    if t.lower() in CODE_OPENERS:
        return 4.1
    if t.lower() in PRONOUNS:
        return -1.4
    if t.lower() == 'the':
        return -0.4
    if t == 'a' or t == 'A':
        return 1.6 if s.startswith(' ') else 3.3
    if t.startswith('#'):
        return 5.1 + min(3.0, 1.6 * (len(t) - 1))
    if t.startswith('//'):
        return 15.9 if '\n' in s else 3.4
    if t.startswith(('"' * 3, "'" * 3)):
        return 5.8
    if t.startswith('/*'):
        return 6.4 if '\n' in s else 8.5
    if all(unicodedata.category(c)[0] in 'PS' for c in t):
        if len(t) > 1 and len(set(t)) == 1 and t[0] in '*^·':
            return 14.8 if t[0] in '*^' else 9.0
        if t[0] in '\"\'`':
            return 0.3
        if t in {'&&', '||'}:
            return 0.0
        return 2.4
    return 0.7


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        value = opening(s)
        return (doc, s, prefix.token_ids[-1], True, s[-100:], 1), value
    _, first, first_id, repeating, tail, position = carry
    same = repeating and prefix.token_ids[-1] == first_id
    t = s.strip()
    value = 0.0
    if same:
        value = opening(s)
    elif position == 1 and first == 'Title' and s == ':':
        value = 31.0
    elif s.startswith(' ') or (tail and not tail[-1].isalnum()):
        word = t.lower()
        if word in {'on', 'upon'}:
            value = 0.57 if word == 'on' else 0.81
            if t == 'On':
                value = 0.39
            context = ' '.join(re.findall(r'[A-Za-z]+', tail)[-3:])
            if DEPENDENCY.search(context):
                value = 0.04 if word == 'on' else 0.25
            if re.search(r'\bso\s*$', tail, re.I):
                value = -0.4
        elif word == 'at':
            value = 0.36
            if re.search(
                r'\b(?:look|aim|attempt|arriv|evaluat)\w*'
                r'(?:\s+\w+)?\s*$', tail, re.I
            ):
                value = -0.08
        elif word in TRANSLATIONS:
            value = TRANSLATIONS[word]
    return (doc, first, first_id, same, (tail + s)[-100:], position + 1), value

programs.haiku:
"""Conjunction detector: the word "and" and its translations, joining two things.

Component layers.1.mlp.down_proj:583 writes a negative value on conjunctions. Its
activation is about -1.4 on English " and", about -2.2 when the "and" follows a comma
(", and the man who ..."), and about -2 to -5 on conjunctions in other languages:
"und" (German), "y" and "e" (Spanish, Italian), "et" (French), "og" and "och"
(Scandinavian), "и" (Russian), "و" (Arabic).

The program predicts, at each token:
  - English "and" (and "And", "AND", "-and"): -1.5.
  - Conjunctions in other languages ("und", "og", "och", "и", "és", "و", "ja", ...): -2.5.
  - Short Romance conjunctions "e", "y", "et", "ed", "ve": -2.5, but only when the text
    in the previous 15 tokens of the same document has fewer than two common English
    words (in English text, "e" and "y" are letters, and they stay near 0).
  - Each of these is multiplied by 1.5 when the previous token is a comma.
  - Every other token predicts 0.
"""

READS = ()

ENGLISH_AND = {" and", " And", " AND", "and", "And", "-and"}
OTHER_AND = {" und", " Und", "und", " og", " och", " и", " И", " és", " şi", " și", " và",
             " ja", " dan", " Et", " و", "و", "αι"}
SHORT_AND = {" y", " e", " et", " ed", " ve"}
ENGLISH_WORDS = {" the", " of", " is", " and", " to", " a", " in", " that", " it", " with",
                 " for", " was", " are", " on", " as", " be", " this", " by"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    t = prefix.position
    # the up to 15 tokens before this one, within the same document, nearest first
    before = []
    for i in range(t - 1, max(-1, t - 16), -1):
        if prefix.document_ids[i] != prefix.document_ids[t]:
            break
        before.append(prefix.token_strings[i])

    if token in ENGLISH_AND:
        value = -1.5
    elif token in OTHER_AND:
        value = -2.5
    elif token in SHORT_AND:
        english_text = sum(w in ENGLISH_WORDS for w in before) >= 2
        value = 0.0 if english_text else -2.5
    else:
        value = 0.0

    if before and before[0] == ",":
        value *= 1.5
    return carry, float(value)

programs.sol:
"""Degree words, especially superlatives licensed by articles or possessives.

More/less are stronger in adjective comparisons than in quantity phrases.
Most/least are strong after 'the', but not in 'at most' or 'at least'.
The same lexical response extends to Romance and some other languages.
Recent word-frequency evidence distinguishes French plus from English
addition, and Portuguese mais ('more') from French mais ('but').
"""
import re
from wordfreq import zipf_frequency

READS = ()
ARTICLES = {'a', 'an', 'the'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their', 'whose', "'s", '’s'}
COPULAS = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
           'become', 'becomes', 'became', 'grow', 'grows', 'grew'}
COUNTS = {'one', 'two', 'three', 'four', 'five', 'six', 'seven',
          'eight', 'nine', 'ten', 'few', 'any'}
DEGREES = {'more', 'most', 'less', 'least', 'plus', 'mais', 'más', 'mas',
           'più', 'moins', 'mehr', 'более', 'menos', 'meno', 'mere', 'mest'}
ENDINGS = {w[i:] for w in DEGREES for i in range(1, len(w))}
WORDS = re.compile(r"['’]s\b|[^\W\d_]+|\d+", re.UNICODE)


def language_score(text, language):
    return sum(zipf_frequency(w, language) for w in WORDS.findall(text)[-20:])


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    context = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    joined = context + token
    # A degree word can be completed by a token fragment: m + ore, ma + is.
    if word not in DEGREES and word in ENDINGS:
        match = re.search(r'([^\W\d_]+)$', joined.lower())
        if match and match[1] in DEGREES:
            word = match[1]
            context = joined[:-len(word)]
    words = WORDS.findall(context.lower())[-8:] if word in DEGREES else []
    prev = words[-1] if words else ''
    before = words[-2] if len(words) > 1 else ''
    value = 0.0
    if word == 'more':
        value = 3.1
        if prev in COPULAS:
            value = 5.1
        elif prev in ARTICLES:
            value = 4.6 if prev != 'the' else 4.1
        elif prev == 'or' or prev in COUNTS or prev.isdigit():
            value = 0.25
        elif prev == 'no':
            value = 1.0
        elif prev in {'have', 'has', 'had', 'need', 'needs', 'want',
                      'wants', 'add', 'learn', 'spend'}:
            value = 1.7
        elif prev == 'and' or context.rstrip().endswith((',', '&')):
            adjective = before if prev == 'and' else prev
            value = 6.8 if adjective.endswith('er') else 3.6
        if token.strip() == 'More':
            value = 3.3 if context.endswith('.') else 1.8
    elif word == 'most':
        value = 0.6
        if prev == 'the' or prev in POSSESSIVES:
            value = 8.7
        elif prev in COPULAS:
            value = 5.3
        elif prev.isdigit() or prev in {
            'second', 'third', 'fourth', 'fifth', 'st', 'nd', 'rd', 'th'
        }:
            value = 7.5
        elif prev == 'and' or context.rstrip().endswith((',', '&')):
            adjective = before if prev == 'and' else prev
            if adjective.endswith('est') or adjective in {'best', 'worst'}:
                value = 12.0
            elif prev == 'and' and 'the' in words[-5:]:
                value = 8.5
        elif context.rstrip().endswith('('):
            value = 6.5
        elif prev in {'i', 'you', 'he', 'she', 'it', 'we', 'they'}:
            value = 6.5
        elif prev in {'at', 'for', 'in', 'of', 'by'}:
            value = -0.15
