            if re.search(r'[.!?][\]\)\d]*$', context):
                value = 0.4
            elif value == 0.6:
                value = 1.7
        elif token.strip() == 'MOST' and value == 0.6:
            value = 4.5
    elif word == 'less':
        value = 1.8
        if prev in ARTICLES:
            value = 3.1
        elif prev in COPULAS:
            value = 2.3
        if prev == 'and' or context.rstrip().endswith((',', '&')):
            adjective = before if prev == 'and' else prev
            value = 4.5 if adjective.endswith('er') else 2.8
        elif prev == 'or':
            value = 1.5
        if token == 'less' and context[-1:].isalpha():
            value = 0.0  # suffix, as in 'careless'
    elif word == 'least':
        value = 2.4 if prev == 'the' else 0.0
    elif word == 'plus':
        french = language_score(context, 'fr') > language_score(context, 'en')
        value = 4.3 if french else 0.1
        if french and prev in {'le', 'la', 'les'}:
            value = 7.3
    elif word == 'mais':
        portuguese = language_score(context, 'pt') > language_score(context, 'fr')
        value = 7.4 if portuguese else -0.7
        if portuguese and prev in {'o', 'a', 'os', 'as'}:
            value = 9.0
    elif word in {'más', 'mas'}:
        value = 6.3
        if prev in {'el', 'la', 'los', 'las', 'lo', 'es', 'son', 'era'}:
            value = 9.0
        if word == 'mas':
            spanish = language_score(context, 'es')
            others = max(language_score(context, lang)
                         for lang in ('en', 'pt', 'fr', 'de', 'id'))
            embedded = not token[:1].isspace() and context[-1:].isalpha()
            if spanish <= others or token.strip() != 'mas' or embedded:
                value = 0.4
    elif word == 'mere':
        danish = language_score(context, 'da') > language_score(context, 'en')
        value = 7.8 if danish else 0.0
    else:
        value = {'più': 3.3, 'moins': 3.6, 'mehr': 0.85, 'более': 2.3,
                 'menos': 1.8, 'meno': 2.6, 'mest': 2.0,
                 '最': 0.4, '更加': 0.4}.get(word, 0.0)
    return (doc, joined[-240:]), value

