"""layers.1.mlp.down_proj:584 - the "more / most" detector.

This component is a comparative/superlative word detector. It is silent on almost every
token and fires on the word itself when that word is a degree word such as "more",
"most", "less", "least", "plus", or its equivalent in another language ("más", "mais",
"più", "mehr", ...). The size depends on the word before it:

- after a determiner, copula or other degree-introducing word ("the most", "le plus",
  "is more", "are less"): strongest;
- after a quantity word ("one or more", "no more", "few more"): about zero;
- after a preposition ("in most cases", "at least"): zero for "most" and "least" (these are
  quantifiers there), still moderate for "more" and "less" ("for more", "with more");
- otherwise, a medium value.

Words from other languages are a flat value, whatever comes before.

The program predicts from the current word and the previous word only, so it is causal and
needs no carry. It returns 0 at the start of a document.
"""

READS = ()

# Activation for each word, by the kind of word before it:
# (after a degree word, otherwise, after a preposition, after a quantity word)
VALUES = {
    "most": (7.5, 2.0, 0.0, 0.0),
    "more": (4.4, 3.0, 3.2, 0.3),
    "less": (2.6, 1.0, 2.2, 1.4),
    "least": (2.1, 0.4, 0.0, 0.0),
    "plus": (2.6, 1.9, 1.9, 1.9),
}
# Other languages' equivalents: one flat value (their activation hardly depends on context).
FOREIGN = {
    "más": 7.0, "mais": 4.2, "mas": 2.8, "più": 3.3, "moins": 2.0, "menos": 1.8,
    "meno": 1.5, "meer": 1.4, "mehr": 0.9, "mere": 0.3, "более": 2.3, "наиболее": 1.6,
}
# Words that make the next "more/most" a degree word ("the most", "is more", "le plus").
DEGREE_BEFORE = {
    "the", "a", "le", "la", "les", "is", "are", "was", "were", "be", "been", "become",
    "became", "its", "their", "his", "her", "'s", "de", "(", "and", ",", "much", "even", "of",
}
# Words that make it a quantity ("one or more", "no more", "few more").
QUANTITY_BEFORE = {
    "or", "one", "two", "three", "no", "few", "once", "any", "further", "some", "couple", "many",
}
# Prepositions ("in most cases", "at least", "with more").
PREPOSITION_BEFORE = {"in", "at", "for", "with", "by", "from", "unlike", "to", "on"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    if word in FOREIGN:
        return carry, float(FOREIGN[word])
    if word not in VALUES:
        return carry, 0.0
    prev = prefix.token_strings[-2].strip().lower()
    degree, other, prep, quantity = VALUES[word]
    if prev in DEGREE_BEFORE:
        return carry, degree
    if prev in QUANTITY_BEFORE:
        return carry, quantity
    if prev in PREPOSITION_BEFORE:
        return carry, prep
    return carry, other

programs.sol:
"""Clause-level time and frequency qualifications have a negative response.

Join word pieces, recognize temporal/modal adverbs and short temporal idioms,
and distinguish a separately tokenized adverb ending from a whole word.
Manner/intensity adverbs have a smaller positive response. This is a lexical
approximation, not a general grammatical parser. A document-opening
'Title:' marker has a separate positive response.
"""
import re

READS = ()

# Each row is a familiar semantic group, with a shared response strength.
GROUPS = (
    (-5.0, 'doubtless'),  # certainty without qualification
    (-4.5, 'formerly traditionally ordinarily normally'),  # prior/customary state
    (-3.7, 'previously originally usually hitherto'),
    # Alternatives, presumptions, and certainty.
    (-3.3, 'otherwise presumably supposedly unquestionably'),
    (-2.6, 'currently typically commonly sometimes initially historically'),
    (-2.4, 'allegedly hopefully ideally'),  # non-asserted state
    (-1.8, 'now often presently apparently reportedly theoretically lately'),
    (-1.5, 'probably likely seemingly generally officially formally'),
    (-1.1, 'recently eventually ultimately once later afterwards subsequently'),
    (-1.1, 'primarily mostly regularly frequently occasionally unfortunately'),
    (-1.0, 'obviously preferably definitely hardly undoubtedly'),
    (-0.6, 'therefore thus consequently basically mainly certainly chiefly'),
    (-0.5, 'earlier soon already thereafter rarely notably'),
    (-0.4, 'ago finally possibly increasingly essentially'),
    (-0.2, 'partly roughly largely fundamentally potentially practically utterly'),
    (-0.2, 'admittedly accordingly secondly literally '
           'intentionally naturally clearly'),
    (-0.2, 'inwardly outwardly'),  # perspective/direction
    (1.1, 'highly heavily strongly severely'),  # intensity of manner
    (0.7, 'seriously freely lightly eagerly desperately specially'),
    (0.35, 'quickly widely deeply greatly gently swiftly dramatically'),
)
ADVERBS = {w: value for value, words in GROUPS for w in words.split()}
ENDING = re.compile(r'[A-Za-z]+$')
ADVERB_ENDINGS = set(
    'ly ally ically ably ily ely ously ingly ively ually'.split()
)
SUBJECT_PRONOUNS = set('i you he she it we they who that there'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word, before, two_back = (
        ('', '', '') if carry is None or carry[0] != doc else carry[1:]
    )
    s = prefix.token_strings[-1]
    tail = ENDING.search(s)
    split = bool(tail and tail.start() == 0 and word)
    if tail:
        if tail.start() == 0:
            word = (word + tail[0])[-60:]
        else:
            two_back, before, word = before, word.lower(), tail[0]
    else:
        word, before, two_back = '', '', ''
    w = word.lower()
    split_ending = split and s.lower() in ADVERB_ENDINGS
    value = ADVERBS.get(w, -0.002)
    if w in ADVERBS and value < -0.05:
        if ((value < -1.2 or split_ending) and word[0].isupper()
                and w not in ('now', 'otherwise', 'unfortunately')):
            value -= 1.1
        if split_ending:
            value -= 2.0
    elif split and s.isalpha() and s.lower().endswith('ly'):
        # A visible -ly ending also responds in names and uncommon words.
        value += 1.5 if s.lower() in ('ly', 'ely', 'ily', 'ingly') else 0.7

    # Temporal readings of otherwise ambiguous short words.
    if w == 'to' and before == 'used':
        # Habitual past, not passive 'is used to ...'.
        value = -4.3 if two_back in SUBJECT_PRONOUNS else -0.05
    elif w == 'once':
        value = -5.8 if before in ('was', 'were') else -0.5
        if before in ('he', 'she', 'it', 'they', 'we', 'the', 'what'):
            value = -2.7
    elif w == 'longer':
        value = -2.7 if before == 'no' else -0.15
    elif w == 'far':
        value = -2.2 if before in ('so', 'thus') else -0.2
    elif w == 'then':
        value = -0.7 if before in ('was', 'were') else -0.12
    elif w == 'long':
        value = -1.8 if before in ('so', 'has', 'have', 'had', 'before') else -0.2
    elif w == 'yet':
        value = -1.8 if before in ('not', 't') else 0.0
    elif w == 'doubt' and before == 'no':
        value = -4.1
    elif w == 'likely':
        if before in ('more', 'less'):
            value = -0.45
        elif before in ('will', 'would', 'he', 'she', 'they', 'and'):
            value = -2.9
    elif w == 'otherwise' and before == 'would':
        value = -6.8
    elif w == 'now' and s.startswith(' '):
        if before in ('right', 'just', 'me'):
            value = -0.65
        elif before in ('is', 'are', 'can', 'will', 'has', 'and', 'but'):
            value = -2.3
    elif w == 'be' and before == 'to' and two_back == 'used':
        value = -4.6
    if w == 'now' and not s.startswith(' ') and not split:
        value *= 0.4
        if prefix.position and '(' in prefix.token_strings[-2]:
            value = -3.2
    if s == ':' and prefix.position >= 2:
        if (prefix.token_strings[-2] == 'Title'
                and prefix.token_strings[-3] == '<|endoftext|>'):
            value = 8.27
    return (doc, word, before, two_back), float(value)

"""Approximate a lon/clon/colon spelling feature, not a topic detector.

It responds most strongly to clone and colon spellings, and to an -on
fragment following l or le. A suffix continuing such a word can retain
some response. Other on/ron fragments are weaker; ordinary long/alone
spellings are not given the large response. A few constructions with the
preposition 'on' instead get a negative value. Unrecognized text is near zero.
Transliteration extends the spelling checks across scripts.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=65536)
def roman(text):
    return anyascii(text).lower()


def response(text, previous, word):
    s, p, w = roman(text), roman(previous), roman(word)
    core = s.strip(' ._-/(')
    # Chinese clone (克隆) and the long syllable in dragon (龙/龍).
    if text == '隆':
        return 8.0 if previous == '克' else 3.3
    if text in ('龙', '龍'):
        return 0.75
    if re.search(r'clon(?:e|es|ed|ing)?$', core):
        if text.startswith(' '):
            return 4.2 if text.lstrip()[0].isupper() else 7.1
        return 4.9
    if 'colon' in core:
        return 3.5
    if core in ('nylon', 'lyon'):
        return 2.8
    if text in (' on', ' upon'):
        if w.startswith('reflect'):
            return -3.0
        if re.match(r'(?:comment|elaborat|expand|build)', w):
            return -1.2
        return -5.5 if w in ('variant', 'variants') else -0.035
    if not s or not s[0].isalpha():
        return 0.0
    # Do not join the two words of a camelCase identifier, such as TableOne.
    new_case = text[:1].isupper() and previous[-1:].islower()
    if re.fullmatch(r'on(?:[aeiysn][a-z]*|)', s) and not new_case:
        if p.endswith(('cl', 'kl')):
            return 9.3
        if p.endswith(('col', 'kol')):
            return 6.8
        if p.endswith(('l', 'le')):
            # Accented Latin on has a weaker response than plain on.
            if text[:1] not in 'oO' and 'LATIN' in unicodedata.name(text[0], ''):
                return 2.0
            return 5.0
        if s.startswith('onic'):
            return 1.7
        return 0.5 if p.endswith(('r', 're')) else 0.15
    if re.fullmatch(r'lon', s):
        if 'HANGUL' in unicodedata.name(text[0], ''):
            return 0.3
        return 8.0 if p.endswith('c') else 5.0
    if re.fullmatch(r'[aei]lon', s):
        return 3.1
    if re.fullmatch(r'[a-z]*loon[a-z]*', s):
        return 5.7 if p.endswith('c') else 1.2
    if re.fullmatch(r'ron(?:[aeiys][a-z]*|)', s):
        return 2.2 if p.endswith(('c', 'k')) else 0.7
    if s.startswith('eron'):
        return -3.1
    if re.fullmatch(r'yon(?:[aeiys][a-z]*|)', s):
        return 1.35
    if re.fullmatch(r'[aei][dk]on', s):
        return 3.35
    if s.isalpha() and not new_case:
        if re.search(r'l(?:e)?on$', w):
            if 'clon' in w or 'klon' in w:
                return 8.5 if text == 'al' else 5.0
            return 3.5 if w.endswith(('colon', 'kolon')) else 1.8
        if w.endswith('cron') and s.startswith('i'):
            return 3.0
        if re.search(r'(?:clo|klo|slo)$', w) and s.startswith('n'):
            return 6.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word = '', ''
    else:
        _, previous, word = carry
    text = prefix.token_strings[-1]
    value = response(text, previous, word)
    match = re.search(r'[^\W\d_]+\Z', word + text, re.UNICODE)
    word = match.group()[-32:] if match else ''
    return (doc, text, word), value

"""Local typesetting and Thai spelling cues, not mathematical reasoning.

Equation environment names and alignment at a LaTeX row break give the
largest positive responses. Isolated Thai vowel marks and short Thai-letter
fragments following them are another positive family. Three small long-a
fragments receive negative values.
A few Unicode formatting symbols and incomplete emoji prefixes are handled
as bytes, so a split character need not decode correctly on its own.
"""
import re
import unicodedata
import regex

READS = ()
INVISIBLE_OPERATORS = tuple(
    ch.encode() for ch in "\N{FUNCTION APPLICATION}\N{INVISIBLE TIMES}"
)

THAI_VOWELS = {
    'ั': 6.1,  # short a above the consonant
    'ิ': 3.0,  # short i
    'ี': 0.55, # long i
    'ึ': 0.3,  # short ue
    'ื': 1.4,  # long ue
    'ุ': 5.0,  # short u below the consonant
}
SYMBOL_BLOCKS = [
    (regex.compile(r'\p{Block=Miscellaneous_Symbols_and_Pictographs}'), 0.5),
    (regex.compile(r'\p{Block=Transport_and_Map_Symbols}'), 1.8),
    (regex.compile(r'\p{Block=Supplemental_Symbols_and_Pictographs}'), 2.0),
]
LATEX_COMMAND_PARTS = {
    'quad': 0.9,
    'qquad': 1.7,
    'eqref': 3.6,
    'nonumber': 2.1,
    'phant': 1.1,  # first token of phantom
    'hs': 1.7,     # first token of hspace
    'tag': 1.0,
    'text': -0.3,
    'neq': 0.6,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, last_bytes = '', b''
    else:
        _, tail, last_bytes = carry
    token = prefix.token_strings[-1]
    raw = last_bytes + prefix.token_bytes[-1]
    text = tail + token
    value = 0.0

    # LaTeX structural markers, distinguished from prose and code ampersands.
    if re.search(r'\\(?:begin|end)\{equation\Z', text):
        value = 12.0 if r'\begin' in text[-25:] else 5.8
    elif re.search(r'\\(?:begin|end)\{equ\Z', text):
        value = 0.75
    elif token.strip() in ('&', '&&', '&='):
        if re.search(r'(?<!\\)\\\\\s*\Z', tail):
            value = 9.3 if token == '&' else 7.8
            if token.strip() == '&=':
                value = 1.5
        elif re.search(r'\\cr\s*$', tail):
            value = 5.7
        elif re.search(r'\\begin\{(?:align\*?|aligned|eqnarray\*?)\}\s*$', tail):
            value = 4.7
        else:
            value = -0.23 if token.strip() == '&&' else -0.1
    else:
        command = re.search(r'\\([A-Za-z]+)\Z', text)
        if command:
            value = LATEX_COMMAND_PARTS.get(command[1], 0.0)

    # These are isolated vowel tokens, not vowels inside whole Thai words.
    if token in THAI_VOWELS:
        value = THAI_VOWELS[token]
    elif token == '็':
        value = 0.0 if tail.endswith('ก') else 3.8
    elif token in ('า', '่า', '้า'):
        value = {'า': -2.7, '่า': -2.1, '้า': -0.6}[token]
    elif token and all('THAI CHARACTER' in unicodedata.name(c, '')
                       and unicodedata.category(c) == 'Lo' for c in token):
        if tail.endswith('ั'):
            value = 6.0 / len(token)
        elif tail.endswith('ุ'):
            value = 3.5 / len(token)
    elif token == '่' and tail.endswith(('ั', 'ุ')):
        value = 3.8

    # Invisible mathematical operators; emoji's three-byte UTF-8 prefix.
    if raw.endswith(INVISIBLE_OPERATORS):
        value = 3.35
    elif (len(raw) >= 3 and raw[-3:-1] == b'\xf0\x9f'
          and 0x80 <= raw[-1] <= 0xbf):
