        first_possible = chr(0x1f000 + (raw[-1] & 0x3f) * 64)
        value = 1.5 if raw[-1] == 0x87 else 0.0  # regional-indicator flags
        for block, response in SYMBOL_BLOCKS:
            if block.fullmatch(first_possible):
                value = response
                break
    elif token == '‰':
        value = -2.2
    return (doc, text[-200:], raw[-3:]), value

"""Abstract Chinese measures oppose ASCII stops in Chinese writing.

The noun rule uses dictionary meanings: time, quantity, manner, proportions,
physical dimensions, standards, and a few related abstract attributes. It
also recognizes these nouns inside a short fused token. A separate rule
predicts a positive signal for ASCII periods near Han text. This leaves
most other tokens at zero. Document and tool boundary markers have small
fixed signals, except an initial end marker. An initial decimal 12 has a
large positive signal on its second digit (and a smaller one on a repeated 2).
"""
import re
from functools import lru_cache
import regex
import cedict

READS = ()
HAN = regex.compile(r'\p{Script=Han}')

# Primary English dictionary meanings, grouped by the kind of attribute.
STRONG = {
    'proportion', 'growth rate', 'extent of a rise', 'strength',
    'tendency',
}
MEASURES = {
    'amount', 'total', 'sum of money', 'average price', 'unit price',
    'speed', 'horizontal', 'direction', 'standard', 'density',
}
ATTRIBUTES = {
    'weight', 'pressure', 'angle', 'size', 'degree', 'temperature',
    'mass', 'price', 'price level', 'house price', 'scale', 'time limit',
    'experience', 'plan', 'impression',
}

@lru_cache(maxsize=10000)
def noun_signal(word):
    if len(word) < 2 or not HAN.fullmatch(word[0]):
        return 0.0
    glosses = cedict.glosses(word)
    value = 0.0
    if glosses:
        first = glosses[0]
        primary = re.sub(r'\([^)]*\)', '', first.split(';')[0]).strip()
        if first.startswith('(concept of) time'):
            value = -1.0
        elif primary in STRONG:
            value = -1.0
        elif primary in MEASURES:
            value = -.6
        elif primary in ATTRIBUTES:
            value = -.4
        elif primary == 'time':
            value = -.4
        elif 'manner' in first or 'means (of doing' in first:
            value = -.8
        elif 'opinion' in glosses:
            value = -.5
    if not value and 2 < len(word) <= 6:
        # Short tokens sometimes fuse a noun with a particle or modifier.
        pairs = [noun_signal(word[i:i+2]) for i in range(len(word)-1)]
        value = min(pairs, default=0.0)
        if word.startswith('的'):
            value *= 1.2
        else:
            value *= .6
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 100, 0, '')
    _, previous, han_age, age, opening = carry
    token = prefix.token_strings[-1]
    value = noun_signal(token.strip())
    if token == '.' and han_age <= 3 and not previous.strip().isdigit():
        value = 2.1
    elif token == '.\n' and han_age == 0:
        value = 1.2
    if token == '<|endoftext|>':
        value = 3.43 if age == 0 else (.4 if han_age <= 8 else .01)
    elif token == '<tool_call>':
        value = .14
    elif token == '<tool_response>':
        value = .10
    elif token == '<|im_start|>' and age == 0:
        value = .33
    if age == 1 and opening == '1' and token == '2':
        value = 4.89
    elif age == 2 and opening == '1' and previous == '2' and token == '2':
        value = 1.91
    han_age = 0 if HAN.search(token) else han_age + 1
    if age == 0:
        opening = token
    return (doc, token, han_age, age + 1, opening), value

"""Possessive determiners and local genitive endings, not possession in general.

A noun's 's is stronger after a determiner and weaker after a capitalized name
or a plural. Plural s-apostrophe also receives a large value. Contractions,
known scientific eponyms and closing quotation marks are discounted. Common
apostrophe encodings are recognized; byte-escaped apostrophe-s gets at least
2.5. The remembered byte tail resets at document boundaries.
"""
import html
import re
from functools import lru_cache
import inflect
import wordnet

READS = ()
POSSESSIVE_DETERMINERS = {
    'their': .61, 'its': .75, 'his': .34, 'her': .16,
    'my': .13, 'our': .17, 'your': .13,
    'leur': .60, 'leurs': .66, 'ses': .50, 'son': .22,
    'sa': .35, 'su': .36, 'sus': .34, 'suo': .69,
    'sua': .62, 'suoi': .71, 'sue': .36,
}
CONTRACTIONS = {
    'it': -.02, 'that': -.11, 'let': .04, 'there': .07,
    'here': .01, 'what': 0., 'he': 0., 'she': -.03,
    'who': .30, 'how': 0., 'where': 0., 'when': 0.,
}
DETERMINER = (
    r'\b(?:the|a|an|this|that|our|my|his|her|their|your|its|'
    r'each|every|any|another|one)\s+$'
)
PLURALS = inflect.engine()

@lru_cache(maxsize=8192)
def word_properties(word):
    w = word.lower()
    noun = 'noun' in wordnet.parts_of_speech(w)
    singular = PLURALS.singular_noun(w)
    plural = bool(singular)
    eponym = any(wordnet.categories(w + "'s " + suffix)
                 for suffix in ('disease', 'law'))
    return noun, plural, eponym


def unescape(text):
    text = html.unescape(text).replace('\x92', '’')
    text = text.replace('â\x80\x99', '’').replace('â€™', '’')
    for escaped in (r'\xe2\x80\x99', r'\u2019', r'\x92'):
        text = text.replace(escaped, '’')
    return re.sub(r"\\+(['’])", r"\1", text)


def genitive_strength(before, plural_apostrophe=False):
    if not plural_apostrophe:
        if before[-1:] in ('.', ')', ']', '!', '`'):
            return 3.1
        before = before.rstrip("'’‘")
    match = re.search(r'([\w]+)$', before)
    if not match:
        return 0.
    word = match[0]
    w = word.lower()
    if plural_apostrophe:
        if not w.endswith('s') or len(w) < 4:
            return 0.
        opening = re.search(r"(?<![\w'‘’])['‘](?!['‘’])[^'’‘\n]*$",
                            before[:match.start()])
        if opening:
            return .1
        if not word_properties(w)[0]:
            return 3. if word[0].isupper() else .5
        return 5.2 if word[0].isupper() else 6.2
    if w in CONTRACTIONS:
        return CONTRACTIONS[w]
    if re.fullmatch(r'NAME_\d+', word):
        return 2.8
    if len(word) == 1 or word.isdigit() or '_' in word:
        return -.2
    noun, plural, eponym = word_properties(word)
    if eponym and word[0].isupper():
        return .2
    value = 2.3 + .6 * noun - 1.0 * word[0].isupper()
    value -= .7 * w.endswith('s') + .7 * plural
    if re.search(DETERMINER, before[:match.start()], re.I):
        value += 1.3
    if w == 'other' and re.search(
            r'\beach\s+$', before[:match.start()], re.I):
        value = 6.4
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = b'' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    word = token.strip().lower()
    boundary = not tail or not chr(tail[-1]).isalnum() or token[:1].isspace()
    value = 0.
    if boundary and word in POSSESSIVE_DETERMINERS:
        value = POSSESSIVE_DETERMINERS[word]
        if token.strip()[0].isupper():
            value *= .9 if word in ('their', 'its', 'his', 'her') else .3
    if token.lower().strip() in (
            "'s", '’s', '‘s', '´s', '′s', '`s', 's', ';s'):
        spelling = (tail + raw).decode('utf-8', errors='replace')
        text = unescape(spelling)
        if re.search(r"['’‘´′`]s$", text, re.I):
            value = genitive_strength(text[:-2].rstrip())
            if spelling.lower().endswith((
                    r'\xe2\x80\x99s', r'\u2019s', r'\x92s')):
                value = max(2.5, value)
        elif token == 's' and re.search(r'\bits$', text, re.I):
            value = .75
    elif unescape(token).strip() in ("'", '’'):
        text = unescape((tail + raw).decode('utf-8', errors='replace')).rstrip()
        value = genitive_strength(text[:-1], plural_apostrophe=True)
    return (doc, (tail + raw)[-512:]), float(value)

programs.haiku:
"""Possessive markers: the component writes "a possessive has just closed here" into the
residual stream, so the next token is the thing possessed.

It fires on the token that ends a possessor noun phrase:
  - the possessive clitic "'s" / "’s" after a noun. It is strongest when a determiner
    comes before the possessor ("the nation's flag", "each job's duties", "a printer's
    wage"), medium after a bare common noun ("patient's"), and weaker after a proper
    name ("Faraday's law");
  - a plural possessive apostrophe after a word ending in s ("the residents' saliva");
  - the possessive determiners "its" and "their" (moderate), "his" (weaker), and a few
    foreign equivalents (su, leur, его, их).
It is silent on contractions after pronouns ("it's", "he's", "that's", "let's"), on
apostrophes that are not possessive (quotes after words, "L'", code), and on her/my/our/your
(which are close to zero).

Stateless apart from the previous two tokens (reset at a document boundary). Values are the
mean activations seen on training text.
"""

READS = ()

# Clitic and apostrophes
POSSESSIVE_S = {"'s", "’s", "'S"}
APOSTROPHES = {"'", "’"}
# Words that make "'s" a contraction (it's, he's, that's, let's), not a possessive
CONTRACTION_HOSTS = {"it", "he", "she", "that", "there", "here", "what", "who", "let", "this", "where", "how"}
# Words that open a noun phrase, so the word after them is a possessor
DETERMINERS = {"the", "a", "an", "each", "every", "your", "his", "her", "my", "our", "its",
               "their", "this", "that", "any", "some", "no", "one", "another", "such"}
# Possessive determiners and their typical strength
POSSESSIVE_DETERMINERS = {
    " its": 0.7, " Its": 0.6,
    " their": 0.6, " Their": 0.5,
    " his": 0.35, " His": 0.35,
    " su": 0.5, " sus": 0.5, " leur": 0.6, " его": 0.4, " их": 0.45,
}


def _in_document(prefix, back):
    """True if the token `back` steps before the current one is in the same document."""
    return len(prefix) > back and prefix.document_ids[-1 - back] == prefix.document_ids[-1]


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower() if _in_document(prefix, 1) else ""
    before = prefix.token_strings[-3].strip().lower() if _in_document(prefix, 2) else ""
    if tok in POSSESSIVE_S:
        if not prev or prev in CONTRACTION_HOSTS:
            value = 0.0
        elif before in DETERMINERS:
            value = 4.0  # "the nation's", "each job's"
        else:
            value = 2.0  # "patient's", "Faraday's"
    elif tok in APOSTROPHES:
        # plural possessive: "the residents'", "the Veterans'"
        value = 3.4 if prev.isalpha() and prev.endswith("s") else 0.0
    else:
        value = POSSESSIVE_DETERMINERS.get(tok, 0.0)
    return carry, float(value)

programs.sol:
"""Approximate a return from quoted speech to narration.

A closing comma-quotation mark is the strongest cue. A quotation begun at
an ordinary sentence/line boundary behaves differently from an embedded
quoted term or title. Questions and exclamations give a smaller response;
full stops give a much smaller one. Remember the opening, not future text.
Also recognize Cyrillic dialogue dashes and a small immediate response on
reporting pronouns he/she. Small ordinary token-specific effects are omitted.
"""

import re
import regex

READS = ()
QUOTES = '\"“”„「」『』«»'
SINGLES = "'‘’"
PUNCTUATION = ',.!?;:，。！？、'


def closing_kind(token):
    s = token.strip()
    if not s or not all(c in QUOTES + SINGLES + PUNCTUATION for c in s):
        return None
    indices = [i for i, c in enumerate(s) if c in QUOTES + SINGLES]
    if not indices:
        return None
    before = s[:indices[0]]
    if any(c in before for c in ',，'):
        return 'comma_quote'
    if any(c in before for c in '!?！？'):
        return 'question_or_exclamation'
    if '。' in before:
        return 'cjk_stop_quote'
    if '.' in before:
        return 'period_quote'
    if any(c in s for c in ',，'):
        return 'quote_comma'
    return 'bare_quote'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry['doc'] != doc:
        carry = dict(doc=doc, recent='', quote=None, just_spoke=False)
    token = prefix.token_strings[-1]
    h, q = carry['recent'], carry['quote']
    role = closing_kind(token)
    boundary = q['boundary'] if q else True
    upper = q['first'].isupper() if q else False
    words = q['words'] if q else 30
    length = q['length'] if q else 300
    title_fraction = q['capitals'] / max(1, words) if q else 0
    value = 0.0

    if role == 'comma_quote':
        if upper:
            if boundary:
                value = -7.8 if title_fraction >= 0.5 else -11.4
            else:
                value = -0.3 if title_fraction > 0.5 else -4.9
        elif words <= 16:
            value = 0.4 if length < 24 else -1.0
        elif h[-1:].isalpha():
            value = -3.4
    elif role == 'question_or_exclamation':
        if boundary:
            value = -5.0 if length < 64 else -1.8
            if any(c in token for c in SINGLES) and length >= 64:
                value = -0.6
        else:
            value = -0.3
        if '\n' in token:
            value *= 0.3
    elif role == 'period_quote':
        if boundary:
            value = (-0.5 if '\n' in token else
                     -1.5 if length < 288 else -0.25)
        else:
            value = -0.25 if upper and words > 5 else 0.08
    elif role == 'cjk_stop_quote':
        value = -4.1 if q and boundary else -0.2
    elif role == 'quote_comma':
        if q and boundary and upper and words >= 3 and title_fraction < 0.5:
            value = -5.5
    elif role == 'bare_quote':
        # A close mark touches the preceding punctuation; a spaced mark opens.
        if not token[:1].isspace() and h.endswith((',', '，')):
            if q and upper:
                value = -10.0 if boundary else -5.0
            elif q is None and token == '“':
                value = -7.0
        elif q and boundary and h.endswith(('。', '？', '！', '…')):
            value = -4.0
    elif token.strip() in ('-', '–', '—') and h.endswith(','):
        if regex.search(r'\p{Script=Cyrillic}', h) and (
            h.endswith(('»,', '",', '”,')) or
            re.search(r'(?:^|[\n.!?])\s*[-–—]\s+\S', h)):
            value = -4.5
    elif token in (' he', ' she') and carry['just_spoke']:
        value = -1.6

    carry['just_spoke'] = role == 'comma_quote' and value < -5
    # Scan only the new token, keeping a small summary of the open quotation.
    for i, c in enumerate(token):
        previous, following = h[-1:], token[i+1:i+2]
        apostrophe = c in "'’" and previous.isalpha() and (
            following.isalpha() or q is None or q['mark'] not in SINGLES)
        mark = c in QUOTES + SINGLES and not apostrophe
        if mark:
            if c in '„「『«‘“':
                closing = c == '“' and (
                    (q is not None and q['mark'] == '„') or
                    (q is None and previous == ','))
            else:
                closing = c in '”」』»’' or (
                    previous and not previous.isspace() and
                    (previous.isalnum() or previous in ',.!?，。！？'))
            if closing:
                q = None
            else:
                before = h.rstrip(' \t' + QUOTES + SINGLES)
                q = dict(mark=c,
                         boundary=not before or before[-1] in '\n.!?。！？',
                         first='', words=0, capitals=0, length=0, in_word=False)
        elif q is not None:
            q['length'] += 1
            if not q['first'] and c.isalpha():
                q['first'] = c
            if c.isalpha():
                if not q['in_word']:
                    q['words'] += 1
                    q['capitals'] += int(c.isupper())
                q['in_word'] = True
            else:
                q['in_word'] = False
        h = (h + c)[-80:]
    carry['recent'], carry['quote'] = h, q
    return carry, float(value)

"""Approximate sparse document-opening and Unicode-spelling responses.

At document starts, recognize code keywords and the second token of Title:,
package com, or <?php. Elsewhere, recognize 宿 (lodging), repeated middle
dots, and a few Korean or pictographic byte fragments. These are spelling
rules, not a general semantic classifier: whole and split character tokens
can receive very different values. Fixed magnitudes summarize repeated
training examples; unrecognized variation is left near zero. State resets
at document boundaries and retains only position, last token, and byte tail.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        position, previous, tail = 0, b'', b''
    else:
        _, position, previous, tail = carry
    joined = tail + token
    state = (doc, position + 1, token, joined[-3:])
    value = -0.25 if position == 0 else 0.0

    if token == '··'.encode():
        value = -1.26
    elif token == '宿'.encode():
        value = 4.8
    elif token == '住宿'.encode():
        value = 1.3
    elif token == '숙'.encode():
        value = 1.2
    elif position == 0:
        if token == b'def':
            value = 2.49
        elif token == b'SELECT':
            value = 2.92
        elif token == b'package':
            value = -0.96
        elif token == b'class':
            value = -1.94
        elif token in (b'import', b'using'):
            value = -0.95
        elif token == b'\\n':
            value = 1.72
        elif token.startswith(b'@'):
            value = -2.0
        elif token == b' .':
            value = -2.10
    elif position == 1:
        if previous == b'Title' and token == b':':
            value = 5.08
        elif previous == b'package' and token == b' com':
            value = 3.33
        elif previous == b'<?' and token == b'php':
            value = 2.34
    elif previous == b'package' and token == b' com':
        value = 1.0
    # These tests see only bytes already read, never a future character.
    if len(token) == 1 and 0x80 <= token[0] < 0xC0:
        if position == 0:
            value = -0.9
        elif joined.endswith('숙'.encode()):  # lodging syllable suk
            value = 6.0
        elif joined.endswith('학'.encode()):  # school/learning syllable hak
            value = 2.3
        elif joined.endswith('편'.encode()):
            value = -2.0
        elif joined.endswith('펼'.encode()):
            value = -3.1
        elif joined.endswith('펴'.encode()):
            value = -1.1
        # Incomplete UTF-8 prefixes also fire before the last byte arrives.
        elif joined.endswith('빠'.encode()[:2]):
            value = -2.6
        elif joined.endswith('편'.encode()[:2]):
            value = -1.65
        elif joined.endswith('原'.encode()[:2]):
            value = 2.1
        elif joined.endswith('☺'.encode()):
            value = -3.3
        elif joined.endswith('☎'.encode()):
            value = -2.9
        elif joined.endswith('☀'.encode()):
            value = -1.3
    return state, value

"""Approximate a contextual response to indefinite-article-shaped tokens.

English a/an depend strongly on the preceding grammatical word or punctuation.
Capital A/An at a sentence boundary differ from letters inside a sentence;
unspaced lower-case forms are often word fragments or variables. German,
Dutch, Hungarian and Scandinavian article forms have stronger negative values.
Scandinavian en/et are distinguished from French/Spanish using recent language
cues. Everything else is left near zero. This is not a full grammatical parser.
"""
import re

READS = ()

# Grammatical contexts immediately before an English noun phrase.
CONTEXTS = (
    ('agency', 'by via using use uses used utilizing', -0.73),
    ('direction', 'to toward towards onto over through across', -0.57),
    ('location', 'in on of from for into upon within', -0.36),
    ('accompaniment', 'with without', -0.23),
    ('at', 'at', -0.14),
    ('comparison', 'as like', -0.05),
    ('coordination', 'and or but nor', -0.37),
    ('condition', 'when while until after before if unless', -0.54),
    ('copula', 'is are am be being been', -0.06),
    ('past_copula', 'was were', 0.13),
    ('possession', 'has have had having', 0.02),
    ('degree', 'such quite rather just only even', -0.07),
    ('complement', 'that whether', -0.53),
)
PRECEDING_WORD = {w: value for _, words, value in CONTEXTS
                  for w in words.split()}
FOREIGN = {
    'ein': -0.98, 'eine': -0.77, 'einer': -0.61,
    'einem': -0.50, 'einen': -0.45, 'eines': -0.05,
    'een': -1.19, 'egy': -1.47, 'ett': -1.85,
}
SCANDINAVIAN = set('och är og ikke inte jeg jag på til dette denna'.split())



def scandinavian(text):
    if any(c in text for c in 'åæøÅÆØ'):
        return True
    words = re.findall(r'[^\W\d_]+', text.lower())
    return any(w in SCANDINAVIAN for w in words)


def english(token, previous, start):
    word = token.strip()
    spaced = token.startswith(' ')
    capital = word[0].isupper()
    longer = word.lower() == 'an'
    if start:
        if capital:
            return -0.19 if longer else 0.13
        if spaced:
            return 0.31 if longer else -0.40
        return -0.17 if longer else 0.01
    boundary = '\n' in previous or any(c in previous for c in '.!?')
    p = previous.strip().lower()
    if capital:
        # Sentence-initial articles versus capital letters/names in running text.
        if boundary:
            value = -0.69 if spaced else -0.34
        elif ':' in previous:
            value = -0.31 if spaced else -0.27
        elif not p:
            value = -0.39 if spaced else -0.06
        elif p.isalpha():
            value = 0.20 if spaced else 0.09
        elif ',' in previous:
            value = 0.24
        elif any(c in previous for c in '+-=*/$\\_'):
            value = -0.34 if spaced else 0.16
        else:
            value = -0.12 if spaced else 0.05
        return value + (0.18 if longer else 0.0)
    if not spaced:
        # Usually a letter, or a fragment attached to another word.
        return (-0.12 if boundary else 0.03) - (0.03 if longer else 0)
    if p.isalpha():
        value = PRECEDING_WORD.get(p, -0.16)
        if p not in PRECEDING_WORD:
            if p.endswith('ing'):
                value -= 0.10
            if p.endswith('s'):
                value -= 0.17
    elif boundary:
        value = -0.26
    elif ',' in previous or ';' in previous:
        value = -0.46
    elif ':' in previous:
        value = -0.11
    elif any(c in previous for c in '([{\"\'+-=*/$\\_'):
        value = 0.10
    elif not p:
        value = -0.04
    else:
        value = -0.08
    return value + (0.22 if longer else 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    tail = '' if start else carry[1]
    token = prefix.token_strings[-1]
    previous = '' if start else prefix.token_strings[-2]
    word = token.strip()
    value = 0.002
    if word in {'a', 'an', 'A', 'An'}:
        value = english(token, previous, start)
    elif token.startswith(' ') or word[:1].isupper():
        lower = word.lower()
        if lower in FOREIGN:
            value = FOREIGN[lower]
            if word[:1].isupper() and lower == 'ein':
                value += 0.10
        elif lower in {'en', 'et'}:
            value = -1.80 if scandinavian(tail) else 0.04
    return (doc, (tail + token)[-1200:]), float(value)

programs.haiku:
"""Indefinite articles, negatively: 'a'/'an' in English and 'ein', 'eine', 'een', 'egy', ...

Layer 1, MLP down-projection, component 598. Its activation is a negative signal on the
indefinite article that opens a noun phrase. How negative depends on the word just before
the article:

- after a verb of use, showing or inclusion (using, use, through, via, which, when, shows):
  about -0.75 ("using a", "shows a")
- after a preposition or a sentence/clause boundary (by, to, of, from, for, or, '.', ','):
  about -0.4 ("by a", "of a", ". A")
- after with, in, on, and, at, into: about -0.25
- anything else: about -0.1
- after a linking verb or 'as' (is, be, are, as, has, have, such): about 0 ("is a", "as a")
- after a verb of making or becoming (was, had, been, made, became, find): about +0.2

Germanic indefinite articles are negative regardless of context: ein -0.95, eine -0.75,
einer -0.6, einem -0.5, einen -0.45, een -1.2, egy -1.45, ett -1.8.

A rare outlier: the colon in a 'Title:' label at the start of a document reads -4.5.

Everything else is 0. Only the previous token and the current one are used.
"""

READS = ()

GERMANIC = {
    " ein": -0.95, " Ein": -0.75, " eine": -0.75, " einer": -0.6, " einem": -0.5,
    " einen": -0.45, " een": -1.2, " ett": -1.8, " egy": -1.45,
}
ENGLISH = {" a", " A", " an", " An", "A"}
USE = {
    " use", " uses", " used", " using", " show", " shows", " showing", " include",
    " includes", " including", " through", " via", " after", " when", " which", " contains",
}
OBJECT = {
    " by", " to", " over", " from", " of", " for", " or", " that", " about", " than",
    " In", " If", " if", " When", " For", ",", ";", ".", "\n", "\n\n", ".\n", ".\n\n", "-",
}
WEAK = {
    " with", " in", " on", " and", " at", " into", " between", " within", " during",
    " upon", " under", " up", " out",
}
LINKING = {
    " is", " be", " are", " were", " as", " has", " have", " such", " not", " take",
    " being", " get", " give", " provide", " provides",
}
RESULT = {
    " was", " had", " been", " make", " made", " makes", " making", " became", " become",
    " becomes", " becoming", " find", " found", " also", " just",
}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in GERMANIC:
        return None, GERMANIC[tok]
    if tok == ":" and len(prefix.token_strings) > 2:
        if prefix.token_strings[-2] == "Title" and prefix.token_strings[-3] == "<|endoftext|>":
            return None, -4.5
    if tok not in ENGLISH or len(prefix.token_strings) < 2:
        return None, 0.0
    prev = prefix.token_strings[-2]
    if prev in USE:
        return None, -0.75
    if prev in OBJECT:
        return None, -0.4
    if prev in WEAK:
        return None, -0.25
    if prev in LINKING:
        return None, 0.0
    if prev in RESULT:
        return None, 0.2
    return None, -0.1

programs.sol:
"""Sparse opening and encoded-text responses, not a full reconstruction.

At document starts, emit token-dependent pulses for chat/tool boundaries
and a few syntax markers. Also recognize the opening number 12 and PHP
open tags (stronger when the tag starts the document). In uninterrupted
base64-like runs, boost digit 1, encoding separators, capitals and digits.
Unmodeled positions get a small background value. Packed documents reset
all counters. The component's smaller contextual fluctuations are omitted.
"""
import string

READS = ()
BASE64 = frozenset(string.ascii_letters + string.digits + '+/=')
BOUNDARIES = {
    '<|im_start|>': 1.724,
    '<|im_end|>': 1.16,
    '<tool_call>': 1.82,
    '</tool_response>': 1.57,
}
OPENING_SYMBOLS = {
    '*': 1.39,
    '->': 0.93,
    '|': -0.54,
    '##': -0.59,
    '"""': -1.02,
    '/*': -0.48,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, previous, length, upper, lower, digits = 0, '', 0, 0, 0, 0
    else:
        _, age, previous, length, upper, lower, digits = carry
    token = prefix.token_strings[-1]
    stripped = token.strip()
    value = 0.001
    if age == 0:
        value = 0.08
        if stripped.isdigit():
            value = -0.08
        elif stripped and not stripped.isascii():
            value = 0.18
        value = BOUNDARIES.get(
            token, OPENING_SYMBOLS.get(stripped, value)
        )
    elif token == 'php' and previous.endswith('<?'):
        value = 3.306 if age < 3 else 1.25
    elif age == 1 and previous == '1' and token == '2':
        value = 2.451

    for ch in token:
        if ch not in BASE64:
            length = upper = lower = digits = 0
        else:
            length += 1
            upper += int(ch.isupper())
            lower += int(ch.islower())
            digits += int(ch.isdigit())
    if length >= 32 and upper >= 3 and lower >= 3 and digits >= 3:
        if token == '1':
            value = 0.55
        elif token == '+':
            value = 0.60
        elif token == '/':
            value = 0.32
        elif len(token) == 1 and token.isupper():
            value = 0.15
        elif token.isdigit():
            value = 0.06
    return (doc, age + 1, token, length, upper, lower, digits), value

"""A local single-letter notation detector.

A one-letter subscript, an argument, or an adjacent initial is positive.
Hyphens, offsets, quotation/formatting ends and whitespace can instead be
negative. Token boundaries matter: a space-prefixed letter behaves differently
from a letter attached to punctuation. Most other tokens stay near zero.
There is also a separate response to replacement-character fragments after Thai.
"""
from functools import lru_cache
import re
import unicodedata as ud
from wordfreq import zipf_frequency

READS = ()
SCALE = 1.0


def latin(s):
    return bool(s) and s.isascii() and s.isalpha()


def letter(s):
    return len(s) == 1 and latin(s)


def variable(s):
    """One Latin letter, optionally attached to opening math punctuation."""
    m = re.fullmatch(r'[([={_:>/]*([A-Za-z])', s)
    return m.group(1) if m else ''


@lru_cache(maxsize=16384)
def frequency(s):
    return zipf_frequency(s.lower(), 'en')


def activation(s, p, q, first):
    t, a, b = s.strip(), p.strip(), q.strip()
    v = variable(a)
    spaced = p[:1].isspace()
    if first or p == '<|endoftext|>':
        if t.isdecimal():
            return -0.18
        if letter(t):
            return 0.02 if s[:1].isspace() else 0.25
        return 0.12
    if '\ufffd' in s and len(p) == 1 and 'THAI' in ud.name(p, ''):
        return -3.5
    if any('SUBSCRIPT' in ud.name(c, '') for c in t):
        return 0.27 if v else 0.03
    if any('SUPERSCRIPT' in ud.name(c, '') for c in t):
        return -0.16 if v else 0.07
    if v:
        if t.startswith('_') and latin(t[1:]):
            return 0.81 if len(t) == 2 else 0.04
        if t.startswith('(') and latin(t[1:]) and len(t) <= 3:
            return 0.27
        if latin(t) and len(t) <= 2:
            if s[:1].isspace():
                if a in ('a', 'I'):
                    return 0.025
                return 0.17 if len(t) == 1 else 0.016
            return 0.016 if t[0].isupper() else -0.018
        if t[:1] in ('-', '‐', '–', '−', '—'):
            if s[:1].isspace():
                return -0.046
            if v.isupper():
                return -0.96 if spaced else -0.22
            return -0.17
        if t[:1] in ('"', '”', '»', '’', "'"):
            if b[-1:] in ('"', '“', '«', '‘', "'"):
                if a in ('a', 'I'):
                    return -0.14
                if t.startswith(('”', '»')):
                    return -2.6
                return -0.44 if t.startswith('"') else -0.20
            return 0.023
        if t.startswith('</'):
            return -1.2
        if t in ('*', '**', '`', '``', '$', '$$', '}'):
            if b.endswith(('*', '`', '$', '{', '>')):
                if t in ('*', '**'):
                    return -1.4
                return -0.95 if t == '$$' else -0.44
            return -0.50 if t == '**' else -0.05
        if s.isspace():
            if '\n' in s:
                if latin(b) and len(b) >= 2 and frequency(a) < 5.6:
                    return -0.63 if spaced else -0.14
                return -0.70 if q.isspace() else -0.25
            if a in ('a', 'I'):
                return 0.004
            return -0.29 if spaced else 0.018
        if '\n' in s and t.startswith(('.', '…')):
            return -1.7 if len(t) in (2, 3) else -0.056
    if t.isdecimal() and a in ('-', '+', '−') and variable(b):
        if spaced:
            return -0.28 if t == '1' else -0.13
        return -0.95 if t == '1' else -0.46
    if letter(t):
        if a.endswith(('_', '_{')) or (a == '{' and b.endswith('_')):
            return 0.75 if variable(b) else 0.13
        if a in ('.', "'", '’') and letter(b) and s[:1].isspace():
            return 0.24
    if '\n' in s and latin(a) and len(a) <= 4 and frequency(a) < 5.6:
        return -0.043
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    p, q = ('', '') if first else carry[1:]
    s = prefix.token_strings[-1]
    value = SCALE * activation(s, p, q, first)
    return (doc, s, p), float(value)

"""A signed detector of local English collocations.

Duration/quantity expressions and motion-verb particles get positive values;
'a while' is especially strong. Conjunction 'while' is slightly negative.
Certainty ('be sure'), evidential passives, and 'given name' are negative.
The constants approximate strengths, not a general semantic classification.
Only two preceding tokens are retained, and document boundaries reset them.
"""
READS = ()

# Indefinite quantities and durations, following the article 'a'.
INDEFINITE = {
    'while': 8.2,
    'long': 2.2,
    'lot': 1.85,
    'whole': 1.55,
    'couple': 1.2,
    'few': 0.9,
    'bunch': 0.6,
    'little': 0.25,
}
GO = {'go', 'goes', 'going', 'gone', 'went'}
GET = {'get', 'gets', 'getting', 'got', 'gotten'}
COME = {'come', 'comes', 'coming', 'came'}
TAKE = {'take', 'takes', 'taking', 'taken', 'took'}
BE = {'be', 'been', 'being', 'is', 'are', 'am', 'was', 'were'}

# The direction/continuation particles of 'go', with their measured strengths.
GO_PARTICLES = {
    'through': 5.0,
    'into': 2.4,
    'on': 2.1,
    'over': 2.1,
    'down': 1.6,
    'back': 1.4,
    'off': 1.4,
    'out': 0.55,
    'in': 0.35,
}


def predict(earlier, previous, current):
    if previous == 'a' and current in INDEFINITE:
        if current == 'long' and earlier in {'for', 'after', 'since'}:
            return 3.2
        return INDEFINITE[current]
    if current == 'awhile':
        return 3.5
    if current == 'while':
        return 4.8 if previous == 'little' else -0.2
    if current == 'time':
        if previous == 'long':
            return 4.4 if earlier == 'a' else 1.5
        return {
            'some': 1.9,
            'hard': 2.3,
            'short': 0.5,
            'longer': 1.6,
            'every': 0.4,
        }.get(previous, 0.0)
    if current == 'long':
        return {
            'how': 1.1,
            'very': 0.55,
            'as': 0.37,
        }.get(previous, 0.0)
    if current in {'years', 'times', 'days', 'ages'}:
        if previous in {'many', 'few', 'several', 'some'}:
            return 1.0 if current != 'days' else 0.5
        if previous in {'these', 'those', 'the'}:
            return 1.1
        if previous == 'for':
            return 2.4 if current == 'ages' else 0.9
    if current == 'of' and previous in {'lot', 'couple'}:
        return 1.3 if previous == 'couple' else 0.55
    if previous in GO:
        if current == 'on' and previous == 'went':
            return 3.1
        if current == 'into' and previous == 'went':
            return 3.0
        return GO_PARTICLES.get(current, 0.0)
    if previous in GET:
        return {
            'into': 3.4,
            'in': 1.2,
            'back': 1.1,
            'on': 1.0,
            'out': 0.35,
        }.get(current, 0.0)
    if previous in COME:
        return {
            'into': 1.0,
            'back': 0.55,
            'on': 0.65,
        }.get(current, 0.0)
    if previous in TAKE and current == 'into':
        return 0.8
    if current == 'name':
        return -3.05 if previous == 'given' else -0.2
    if current == 'sure':
        return {
            'be': -4.8,
            'am': -1.8,
            "'m": -1.8,
            '’m': -1.8,
            'is': -1.2,
            'not': -0.5,
        }.get(previous, 0.0)
    if current in {'seen', 'found', 'known', 'shown', 'heard'}:
        if previous == 'be':
            return {
                'seen': -1.2,
                'found': -0.95,
                'known': -0.65,
                'shown': -0.3,
                'heard': -1.8,
            }[current]
        if previous == 'been':
            return -0.8
        if previous in BE:
            return -0.25
        if current == 'known' and previous in {'best', 'better', 'well', 'also'}:
            return -1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        earlier = previous = ''
    else:
        _, earlier, previous = carry
    token = prefix.token_strings[-1]
    current = token.strip().lower()
    # Leading whitespace distinguishes a new word from a subword continuation.
    value = predict(earlier, previous, current) if token[:1].isspace() else 0.0
    return (doc, previous, current), value

programs.haiku:
"""Layer-1 MLP neuron 602 (down_proj component 602), read as a phrase detector.

The neuron is near 0 on most tokens. It fires on the second word of a few set phrases:
Positive:
  * "a while" / "awhile" (strongest, about 8), "little while"
  * "a long", "a lot", "a whole", "a couple", "a few", "a difference", "a former",
    "a real", "a change", "an example" (about 1 to 2); "lot of", "couple of" (about 1)
  * a particle after a go-verb: "go through" / "went through" (about 5), "get into",
    "went on", "go along", "go over", "go back", "get rid" (about 1 to 3)
  * "long time", "long way", "hard time", "some time" (about 2.5 to 3.5); "how come" (about 5)
  * "not really" / "n't really" (about 2); "I wonder" (about 3.5); "I feel", "I mean" (about 1.4)
  * time spans after a quantifier: "many years", "few years", "many times" (about 1)
Negative:
  * "be sure" / "Be sure" (about -4.5), "was/am sure" (about -2)
  * "given name" (about -3); "a name", "a moment", "a century" (about -1)
  * "be/been/also/well/best seen/found/known/shown" (about -1)
  * "'ve got" / "just got" (about -1.2); "no doubt" / "no idea" (about -1)
  * a run of "··" dot leaders (about -1.1)
The program reads only the current token and the one before it.
"""

READS = ()

GO_VERBS = {"go", "going", "went", "gone", "goes", "get", "getting", "got", "been"}
AFTER_GO = {"through": 5.0, "along": 3.0, "into": 2.5, "on": 2.0, "over": 1.7, "back": 1.1, "rid": 1.5}
AFTER_A = {"while": 7.5, "long": 2.4, "lot": 1.8, "difference": 1.7, "whole": 1.5, "couple": 1.2,
           "few": 0.8, "different": 0.7, "former": 1.1, "real": 1.0, "change": 1.1, "example": 0.8,
           "name": -1.0, "moment": -1.0, "century": -1.0}
QUANTIFIERS = {"many", "few", "several", "these", "those", "some", "for", "couple", "past"}
TIME_SPANS = {"years", "times", "days", "ages", "weeks", "months"}
NEGATIONS = {"not", "never", "n't", "'t", "’t"}
BE_VERBS = {"be", "been", "am", "is", "are", "was", "were", "'m", "’m", "being"}
PASSIVE = {"seen", "found", "known", "shown", "heard"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    else:
        prev = _word(prefix.token_strings[-2])
    if word == "··":
        return carry, -1.1
    if word == "awhile":
        return carry, 6.0
    if word == "while" and prev == "little":
        return carry, 4.5
    if word in AFTER_A and prev in {"a", "an"}:
        return carry, AFTER_A[word]
    if word in AFTER_GO and prev in GO_VERBS:
        return carry, AFTER_GO[word]
    if word == "come" and prev == "how":
        return carry, 5.0
    if word in {"time", "way"} and prev in {"long", "hard", "some"}:
        return carry, 2.5
    if word == "really" and prev in NEGATIONS:
        return carry, 2.0
    if word == "wonder" and prev == "i":
        return carry, 3.5
    if word in {"feel", "mean"} and prev == "i":
        return carry, 1.4
    if word == "of" and prev in {"couple", "lot"}:
        return carry, 1.0
    if word in TIME_SPANS and prev in QUANTIFIERS:
        return carry, 1.0
    if word == "sure" and prev == "be":
        return carry, -4.5
    if word == "sure" and prev in BE_VERBS:
        return carry, -2.0
    if word == "name" and prev == "given":
        return carry, -3.0
    if word == "got" and prev in {"'ve", "’ve", "just"}:
        return carry, -1.2
    if word in {"doubt", "idea"} and prev == "no":
        return carry, -1.0
    if word in PASSIVE and prev in {"be", "been", "also", "well", "best"}:
        return carry, -1.0
    return carry, 0.0

programs.sol:
"""A sparse syntax-and-quotation approximation.

Negative responses mark type/static imports, exported declarations, the colon
in an initial Title: label, escapes, and left-facing quotes used at word ends.
A remembered opening quote distinguishes an apparent wrong-way closing quote.
Ordinary right double quotes and repeated middle dots have positive responses.
Everything else is nearly silent; this does not model general word identity.
"""
import regex

READS = ()
CJK = regex.compile(r'[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}]')
DOUBLE_QUOTES = set('“„”«»‹›"')
ESCAPES = {'d': -3.1, 'w': -2.8, 's': -3.8, 'D': -1.0,
           'r': -0.8, 'db': -1.3, 'hs': -0.25}
REGEX_MARKERS = ('regex', 'regexp', '.match(', 'replace', 'grep ', 're.', 'r"', "r'")


def predict(token, previous, before, quote, escaped, context):
    word, prior = token.strip(), previous.strip()
    if prior == 'import' and word in {'type', 'static'}:
        value = -10.5 if word == 'type' else -4.7
        return value if previous == 'import' else value * 0.45
    if prior == 'export' and word in {'interface', 'type'}:
        value = -7.2 if word == 'interface' else -3.4
        return value if previous == 'export' else value * 0.5
    if prior == 'public' and word == 'interface':
        return -1.0
    at_start = not before or '<|endoftext|>' in before
    if prior == 'Title' and token == ':' and at_start:
        return -6.478
    if previous.endswith('\\') and word in ESCAPES:
        is_regex = any(m in context.lower() for m in REGEX_MARKERS)
        if word in {'d', 'w', 's', 'r'} and is_regex:
            return -2.5 if word == 'r' else -7.0
        if word == 'd' and previous.endswith('^\\'):
            return -1.1
        return ESCAPES[word]
    if '\\' in token:
        if word in {'\\_', '\\/', '\\s'}:
            return {'\\_': -1.05, '\\/': -1.9, '\\s': -2.9}[word]
        if token == '\\' and escaped and previous[-1:].isalnum():
            return -1.1
        if '\\n' not in token and '\\t' not in token:
            quoted_end = token.endswith('\\') and any(q in token for q in ('"', "'", '`'))
            return -0.5 if quoted_end or token == "\\'" else 0.0
    if token == '.ts':
        return -0.48
    if len(word) >= 2 and set(word) == {'·'}:
        return 1.4
    marks = [c for c in token if c in '“‘«‹„']
    if marks:
        mark = marks[0]
        if any(c.isalnum() for c in word.replace('‘s', '')):
            return 0.05
        head = token[:token.index(mark)]
        if head and head[-1] in ',，、:：”':
            return -0.02
        attached = previous and not previous[-1:].isspace() and not token[0].isspace()
        cjk = bool(CJK.search(previous[-1:]))
        word_end = previous[-1:].isalnum() or previous[-1:] == '™'
        if mark == '‘' and attached and not cjk and word_end:
            return -6.5
        if mark == '“' and attached:
            if quote == '“' and word_end:
                return -3.0 if cjk else -7.0
            return 0.05 if cjk else -1.5
        if mark in '«‹' and attached:
            return -1.5
        return -0.02 if token[0].isspace() else 0.0
    if '”' in token and len(word) <= 4:
        return 0.2
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, quote, escaped, context = '', '', '', False, ''
    else:
        _, previous, before, quote, escaped, context = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, before, quote, escaped, context)
    for char in token:
        if char == '“':
            if quote in {'“', '„'}:
                quote = ''
            elif (token.startswith(' ') or not previous
                  or previous[-1:].isspace() or CJK.search(previous[-1:])):
                quote = '“'
            else:
                quote = ''
        elif char == '„':
            quote = '„'
        elif char in DOUBLE_QUOTES:
            quote = ''
    split_quote = previous.endswith('\\') and token.startswith('"')
    if (token.count('\\"') + split_quote) % 2:
        escaped = not escaped
    context = (context + token)[-160:]
    if '<|endoftext|>' in token:
        quote, escaped, context = '', False, ''
    return (doc, token, previous, quote, escaped, context), value

"""Approximate a document-start response and a horizontal-gap response.

The initial token (including an unchanged initial run) gets a coarse value
from punctuation, script, English determiners, word frequency and dictionary
parts of speech. Determiners and word-like tokens tend to be negative;
digits and many punctuation marks are positive. These are class averages,
not a per-token lookup. Later, respond to gaps within a line, not indentation:
space runs and tabs are positive, with weaker responses for long gaps.
Ordinary later tokens get zero. State resets at each document boundary.
"""
from functools import lru_cache
import unicodedata
from wordfreq import zipf_frequency
import wordnet
import regex

READS = ()
ARTICLES = frozenset(('a', 'an', 'the'))
DEMONSTRATIVES = frozenset(('this', 'that', 'these', 'those'))

@lru_cache(maxsize=8192)
def beginning(s):
    w = s.strip()
    lead = s.startswith(' ')
    if s.startswith('<|'):
        return -5.6
    if not w:
        if '\n' in s or '\r' in s:
            return 2.46 if s.strip('\r\n') == '' else 0.4
        return 1.48 if s == ' ' else -1.3
    if w.isdecimal():
        return 1.85
    if w == '�':
        return -1.4
    if all(unicodedata.category(c)[0] in 'PS' for c in w):
        if w[0] in '\'"“‘#\\':
            return -2.5
        if w in {':', '=', '?'}:
            return 0.1
        return 0.3 if lead else 1.5
    low = w.lower()
    if low in ARTICLES:
        return -6.2 if lead else -4.6
    if low in DEMONSTRATIVES:
        return -5.7
    if len(w) == 1:
        if w.isascii():
            return -0.25 if lead else 0.8
        if regex.fullmatch(r'\p{Script=Han}', w):
            return -0.4
        return -2.2 if lead else -1.4
    if not w.isascii():
        return -4.3 if lead else -2.0
    freq = zipf_frequency(w, 'en')
    pos = wordnet.parts_of_speech(low)
    if lead:
        if 'noun' in pos:
            return -2.6
        if 'adjective' in pos or 'adverb' in pos:
            return -4.5
        if 'verb' in pos:
            return -3.8
        return -3.7 if freq >= 5.5 else -3.0
    if freq >= 5.5:
        return -3.8
    if pos == {'noun'}:
        return -0.5
    if 'noun' not in pos and ('verb' in pos or 'adjective' in pos):
        return -2.5
    return -1.2

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        content, initial = False, token
    else:
        _, content, initial = carry
        if token != initial:
            initial = None
    if initial is not None:
        value = beginning(s)
    elif s.isspace() and '\n' not in s and '\r' not in s:
        if not content:
            value = -0.03
        elif '\t' in s:
            value = 0.35 if len(s) == 1 else 1 / (1 + len(s) / 6)
        elif '\xa0' in s:
            value = 0.0 if len(s) == 1 else 0.2
        elif len(s) == 1:
            value = 0.0
        else:
            value = 0.59 if len(s) <= 16 else 0.34
    else:
        value = 0.0

    # Track whether this line already contains something other than whitespace.
    lines = s.replace('\r', '\n').rsplit('\n', 1)
    if len(lines) > 1:
        content = bool(lines[-1].strip())
    else:
        content = content or bool(s.strip())
    return (doc, content, initial), value

"""Approximate the component's large document-start pulse.

The first token gets a type-dependent baseline: alphabetic Latin tokens are
most negative, other scripts and punctuation less so, and whitespace is near
zero. Chat delimiters have their own baselines. Later tokens get zero: this
omits the smaller, token-specific and context-dependent interior responses.
"""
import unicodedata

READS = ()


def initial_value(text):
    word = text.strip()
    if text == '<|im_start|>':
        return -0.3814
    if text == '<|im_end|>':
        return -0.5627
    if text == '<|endoftext|>':
        return 0.1105
    if not word:
        return 0.15 if '\n' in text else 0.01
    if word.isdigit():
        return -0.40
    if word.isascii():
        if word.isalpha():
            return -0.84
        if all(not c.isalnum() for c in word):
            return -0.37
        return -0.70
    if any('CJK' in unicodedata.name(c, '') for c in word):
        return -0.39
    if any('CYRILLIC' in unicodedata.name(c, '') for c in word):
        return -0.60
    return -0.56


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry != document
    value = initial_value(prefix.token_strings[-1]) if first else 0.0
    return document, value

"""Approximate a local consonant-fragment response.

P after T/D/F is strongly negative, especially in matching capitals. Short
TP/DP/FP tokens also respond, with token boundaries and case modulating size.
Smaller rules handle T-to-K/F and one-letter acronym continuations.
Latin and Cyrillic share spelling rules. Small Arabic rules give positive
responses to medial T+M/D/emphatic-S and negative T+K/H responses. A separate
rule recognizes a document-initial 'Title:' label. Unmatched tokens are zero
apart from a small positive background for short P fragments.
"""
from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()

# Magnitudes: uppercase, lowercase, then a change of case.
SINGLE_P = {
    't': (11.0, 2.0, 1.2),
    'd': (5.5, 3.7, 0.0),
    'f': (7.3, 2.2, 0.2),
}
P_FRAGMENT = {
    't': (7.7, 2.4, 1.1),
    'd': (3.7, 1.7, 0.0),
    'f': (2.9, 1.3, 0.15),
}
# Magnitudes of a short token ending in these consonant-P pairs.
INTERNAL_P = {
    't': (4.9, 4.2),
    'd': (1.0, 1.0),
    'f': (2.6, 1.4),
}


@lru_cache(maxsize=16000)
def spelling(text):
    # Transliteration here is spelling, not a pronunciation of other scripts.
    if regex.search(r'[^\p{Latin}\p{Cyrillic}\p{Common}\p{Inherited}]', text):
        return ''
    return anyascii(text)


def predict(previous, current):
    # Written Arabic consonant combinations within a word, not new words.
    if (len(current) == 2 and current[0] == 'ت' and previous
            and regex.fullmatch(r'\p{Script=Arabic}', previous[-1])):
        positive = {'م': 3.0, 'د': 3.2, 'ص': 3.0}.get(current[1])
        if positive is not None:
            return positive
    if (previous.endswith(('ت', 'ط')) and not current[:1].isspace()
            and len(current) <= 2):
        if current.endswith('ك'):
            return -1.8
        if current.endswith('ح'):
            return -1.6 if len(current) == 1 else -1.3
    p, s = spelling(previous), spelling(current)
    raw = s.strip()
    letters = raw.strip('.-_')
    if not letters.isalpha():
        return 0.0
    low, capitals = letters.lower(), letters.isupper()
    value = 0.2 if low == 'p' else (
        0.05 if len(low) <= 2 and 'p' in low else 0.0
    )

    if (capitals and len(low) == 3 and low[0] == 't'
            and low[-1] == 'p' and low[1] not in 'aeiouytdf'):
        value -= 1.5
    if 2 <= len(low) <= 3 and low.endswith('p'):
        consonant = low[-2]
        if consonant in INTERNAL_P:
            size = 1.25 if len(low) == 3 else 1.0
            if (letters == 'tp' and p and p[-1] in 'aeiou'
                    and not s[:1].isspace()):
                size *= 0.15
            magnitude = INTERNAL_P[consonant][0 if capitals else 1]
            if consonant == 'd' and len(low) == 2 and not s[:1].isspace():
                magnitude = 2.3 if capitals else 2.1
            value -= magnitude * size
            if letters == 'TP' and p.endswith(('M', 'N')):
                value -= 3.6

    # A new word is not a continuation, except in spelled-out letter strings.
    if not p or not p[-1].isalpha():
        return value
    if s[:1].isspace() and len(p.strip()) != 1:
        return value
    last = p[-1]
    bridge = 0.3 if raw[:1] in '.-_' else 1.0
    case = 2 if last.isupper() != letters[0].isupper() else (
        0 if last.isupper() else 1
    )
    if low == 'p':
        strength, table = 1.0, SINGLE_P
    elif low.startswith('p') and len(low) <= 3:
        strength = 0.8 if letters == 'PS' else (
            0.5 if capitals and len(low) == 2 else 0.15
        )
        table = P_FRAGMENT
    elif len(low) == 2 and low.endswith('p'):
        strength, table = 0.15, P_FRAGMENT
    else:
        strength, table = 0.0, P_FRAGMENT
    if last.lower() in table:
        value -= bridge * strength * table[last.lower()][case]
    elif last.isupper() and letters[0].isupper() and last.lower() not in 'aeiouy':
        value -= bridge * strength * 0.25

    if len(low) <= 2 and low[0] in 'kf' and last.lower() == 't':
        amount = 1.1 if low[0] == 'k' else 0.6
        amount *= 1.0 if len(low) == 1 else 0.5
        amount *= 0.3 if case == 2 else 1.0
        if last.isupper() and capitals:
            amount += 0.5
        value -= bridge * amount
    if len(low) == 1 and capitals and p.strip().isupper():
        if p.endswith(('TP', 'FP', 'DP')):
            value -= 2.7
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1], carry[2] + 1
    current = prefix.token_strings[-1]
    value = predict(previous, current)
    if position == 1 and previous == 'Title' and current == ':':
        value = -4.48
    return (doc, current, position), value

"""Growth, cultivation and rearing, with a separate geographic 'of' response.

The largest response is to the nurture/rearing character 养 / 養.  English
culture is much stronger in a biological laboratory context than in a social
one. Splitting growth/culture words into pieces strengthens the spelling
response. Curing, catching and colonies have smaller lexical responses.
Geographic and culture/collective nouns followed by 'of' are also negative. Other
tokens receive zero. The UTF-8 decoder and recent text reset per document.
"""
import codecs
import re
from functools import lru_cache
import cedict

READS = ()

TERRITORY = {
    'country': -3.2, 'nation': -3.0,
    'republic': -1.7, 'kingdom': -2.3, 'state': -1.4,
    'city': -2.8, 'county': -2.8, 'town': -1.5, 'village': -1.2,
    'isle': -0.8, 'isles': -1.5,
    'province': -0.7, 'municipality': -1.0,
    'island': -1.4, 'borough': -0.4, 'coast': -1.0,
    'government': -1.0,
}
BIOLOGY = re.compile(
    r'\b(?:plant|bacter|cell|crop|seed|tuber|fung|microb|tissue|'
    r'embryo|inoculat|incubat|nutrient|broth|assay|agar|'
    r'anther|sludge|plasma|serum|liquid|in vitro|viab|6-well|'
    r'amino|isotope|phage|enzyme|protein)|\d+\s*ml\b'
)
REARING = {'양': -5.0, 'dưỡng': -7.0, 'nuôi': -2.4}
GROW = {'grow': -2.1, 'grows': -1.3, 'grew': -1.3,
        'grown': -2.5, 'growing': -1.7}


@lru_cache(maxsize=2048)
def nurture_word(word):
    """Compounds dilute the otherwise very strong rearing character."""
    if len(word) > 2:
        return -2.0
    glosses = cedict.glosses(word)
    first = glosses[0] if glosses else ''
    if first == 'to cultivate':
        return -1.4
    if 'breed' in first or first == 'to maintain':
        return -5.2
    return -2.6


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before = ''
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
    else:
        _, before, decoder = carry
    partial_character = bool(decoder.getstate()[0])
    token = decoder.decode(prefix.token_bytes[-1])
    s = token.lower()
    prior = before.lower()
    text = before + token
    m = re.search(r'[a-z]+$', (prior + s)[-80:])
    word = m.group() if m else ''
    bare = s.strip()
    split = bool(s and s[0].isalpha() and prior and prior[-1].isalpha())
    # Notice the arriving root, not later adjectival endings like '-ural'.
    cult_piece = split and (
        (prior.endswith('c') and re.fullmatch(
            r'ult(?:i(?:v.*)?|ur(?:e[ds]?|ing)?)?', bare))
        or (prior.endswith('cult') and re.fullmatch(r'ur(?:e[ds]?|ing)|iv.*', bare))
    )
    needs_biology = bare in ('growing', 'growth', 'culture', 'cultures', 'cult')
    needs_biology = needs_biology or bool(cult_piece)
    needs_biology = needs_biology or (split and prior.endswith('g') and bare == 'rowth')
    biology = needs_biology and bool(BIOLOGY.search(prior[-240:]))
    value = 0.0

    if any(c in token for c in '养養'):
        if bare in ('养', '養'):
            # Nutrition's second character is weaker than rearing on its own.
            if before.endswith(('营', '營', '栄', '榮')):
                value = -3.6
            else:
                value = -15.0 if partial_character else -8.2
        else:
            value = nurture_word(bare)
    elif bare in REARING:
        value = REARING[bare]  # Korean / Vietnamese rearing vocabulary.
        if bare == '양' and partial_character:
            value = -7.0
    elif bare in ('of', '-of'):
        previous = re.search(r'([a-z]+)$', prior)
        if previous:
            noun = previous.group(1)
            value = TERRITORY.get(noun, 0.0)
            if before.endswith('State'):
                value = -2.3
            elif before.endswith('Province'):
                value = -1.7
            elif noun in ('culture', 'cultures', 'cult'):
                value = -2.6
            elif noun in ('collection', 'species', 'family'):
                value = -0.5
    elif bare in GROW:
        value = GROW[bare]
        if bare == 'growing':
            value = -2.4 if biology else -1.4
    elif bare == 'growth':
        value = -1.7 if biology else -0.25
    elif split and prior.endswith('g') and bare in ('row', 'rown', 'rowing'):
        value = -5.5
    elif split and prior.endswith('g') and bare == 'rowth':
        value = -1.6 if biology else -0.7
    elif split and prior.endswith('grow') and bare in ('er', 'ers'):
        value = -3.5
    elif bare.startswith('cultiv'):
        if bare.startswith('cultivating'):
            value = -4.0
        elif bare.startswith('cultivated'):
            value = -1.6
        else:
            value = -2.6
    elif bare in ('culture', 'cultures'):
        value = -6.0 if biology else -1.3
        if not token.startswith(' ') and not biology:
            value = -2.7
    elif bare in ('cultured', 'culturing'):
        value = -4.3 if bare == 'cultured' else -5.0
    elif bare == 'cult':
        value = -5.0 if biology else -3.3
        if split and not (word.startswith('cult') or cult_piece):
            value = -0.8
    elif cult_piece:
        value = -6.0 if biology else -3.8
        if before.endswith('C'):
            value *= 1.5
    elif bare in ('cure', 'cures', 'cured', 'curing') or (
        split and re.fullmatch(r'(?:un|mani|pedi|light)?cur(?:e[ds]?|ing)', word)
    ):
        value = -4.8 if split else (-3.3 if bare == 'curing' else -2.5)
    elif split and len(bare) >= 3 and (
        word in ('catch', 'catches', 'catching', 'catcher', 'cage')
        or word.endswith('catch')
    ):
        value = -3.5
    elif bare in ('catch', 'caught', 'catching', 'catches', 'catcher'):
        if bare == 'catcher':
            value = -1.7
        else:
            value = -0.7 if bare == 'caught' else -0.4
    elif bare in ('colony', 'colonies'):
        value = -0.9
    return (doc, text[-400:], decoder), value

programs.haiku:
"""Cultivation / growth detector with a 'country of' rule.

Activation is negative (strongest for Chinese 养/養 'raise, cultivate', and English
cult-/cultur-/cure words) on words about cultivating, culture and growing, and on
'of' right after a territory noun ('country of', 'state of', 'City of', 'Republic of').
Everything else is predicted as 0. Magnitudes are typical activations, not fitted.
"""
READS = ()

TERRITORY_NOUNS = {"country", "city", "state", "republic", "kingdom", "town", "island",
                   "province", "colony", "isle", "isles", "cities", "states", "county"}
CULTURE_WORDS = {"cult", "cultured", "culture", "cultures", "cultura", "cultivation",
                 "cultivate", "cultivated", "cultivating", "ulture", "cure", "cured",
                 "cures", "curing"}
GROWTH_WORDS = {"grow", "grew", "grown", "growing", "growth", "grows"}
RAISE_CHARS = set("养養")          # Chinese: raise / cultivate / nourish (养殖, 养护, 培养)
RAISE_WORDS = {"nuôi"}             # Vietnamese: raise / rear


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word == "of" and prev in TERRITORY_NOUNS:
        return None, -3.0
    if raw and raw[0] in RAISE_CHARS:
        return None, -6.0
    if word in RAISE_WORDS:
        return None, -3.0
    if word in CULTURE_WORDS:
        return None, -2.5
    if word in GROWTH_WORDS:
        return None, -2.0
    return None, 0.0

"""Layer 1 MLP down-projection, component 610: a detector for the spelled "awn / aun"
vowel-nasal sound, with weaker negative responses to the "ar / aar" r-sound, to Dutch and
German "waar / naar / daar", and to "war".

The component is spiky: most positions are near 0. It turns on at the word piece that
spells the "-awn" or "-aun" sound, in three cases:
  1. Whole pieces with that sound: "lawn", "spawn", "pawn", "awning", "spawned", "Dawn".
  2. A nasal piece (n, nt, ne, ns, un, una, wn, ning, and the Cyrillic and katakana "un")
     right after a piece that ends in an open "a / aw / au / ow / av" sound, as when a word is
     split: "sha|un", "aw|nt", "Brow|ne".
  3. The "n" after "am" in the misspelling "Huam|n" (Human), which recurs in some
     knowledge-base text.
An r-piece (ar, ars, aar, ahr) after the same open-vowel piece pushes the other way ("Da|ar",
"Wa|ar"), as do the whole Dutch and German words waar, naar, daar, and "Wars". "drawn" and
"withdrawn" are common whole words that contain "awn" but do not fire, so they are excluded.
Everything else predicts 0.
"""

import re

READS = ()

AWN_SOUND = re.compile(r"(awn|avn|aun)(s|ing|ed|er)?$")
NOT_AWN = {"drawn", "withdrawn"}
NASAL_PIECES = {
    "n", "nt", "na", "ne", "ns", "un", "uns", "unt", "una", "wn", "ning",
    "ун", "ウン",
}
OPEN_VOWEL_END = re.compile(r"(a|aw|au|ow|av|а|у|о|ア|カ|ラ|タ|サ)$")
R_PIECES = {"ar", "ars", "aar", "ahr"}
DUTCH_AAR = re.compile(r"(aar|ahr|wars)$|waar$|naar$|daar$")
WAR_WORDS = {"war", "wah", "wa", "wow", "warren"}


def _core(text):
    """The token without its leading space, lowercased."""
    return text.strip().lower()


def _is_piece(text):
    """A word piece: letters with no leading space, so it continues the word before it."""
    return not text.startswith(" ") and text.strip().isalpha()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    x = _core(cur)
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _core(prefix.token_strings[-2]) if same_doc else ""
    ends_open = bool(prev) and prev.isalpha() and OPEN_VOWEL_END.search(prev) is not None

    if AWN_SOUND.search(x) and x not in NOT_AWN:
        return None, 5.0
    if _is_piece(cur) and x in NASAL_PIECES and ends_open:
        return None, 5.0
    if cur == "n" and _is_piece(cur) and prev.endswith("am"):
        return None, 1.2
    if _is_piece(cur) and x in R_PIECES and ends_open:
        return None, -3.0
    if DUTCH_AAR.search(x):
        return None, -1.5
    if x in WAR_WORDS:
        return None, -0.5
    return None, 0.0

programs.sol:
"""English noun-to-subject transitions, especially unmarked relative clauses.

For example, the subject in 'the things you ...' receives a positive pulse.
A short dictionary-based noun-phrase heuristic finds the preceding antecedent.
Pronouns receive the strongest pulses; 'the' receives weaker ones, except after
'what'. Common ambiguous words, time expressions, and fronted prepositional
phrases are downweighted. Inflected reporting predicates after 'this'/'that' are
not treated as nouns. Names and fine lexical differences are omitted.
"""
import re
from functools import lru_cache
import wordnet
import wordfreq

READS = ()
PRONOUNS = set('i you he she it we they'.split())
AUXILIARIES = set('am is are was were be been being do does did have has had '
                  'can could will would shall should may might must ought'.split())
PREPOSITIONS = set('to of in on at for from with without by about over under '
                   'into through between among as than after before during '
                   'since until upon within'.split())
RELATIVES = set('what which that who whom whose where when why how whether'.split())
DETERMINERS = set('a an the this that these those my your his her its our their '
                  'each every any some no all both either neither another such'.split())
PHRASE_DETERMINERS = DETERMINERS | set(
    'other many few several multiple most more less least enough what which whose'.split())
INDEFINITE_THINGS = set('something anything everything nothing'.split())
FUNCTION_WORDS = PRONOUNS | AUXILIARIES | PREPOSITIONS | RELATIVES | DETERMINERS


@lru_cache(maxsize=32768)
def parts(word):
    return wordnet.parts_of_speech(word)


@lru_cache(maxsize=32768)
def frequency(word):
    return wordfreq.zipf_frequency(word, 'en')


def noun_phrase(text, last_match):
    """Return 0 for no noun phrase, 1 for a phrase, 2 for a fronted adjunct."""
    raw = last_match[1]
    word = raw.lower()
    if word in FUNCTION_WORDS or word in PHRASE_DETERMINERS:
        return False
    if 'noun' not in parts(word) and not (raw.isupper() and len(raw) > 1):
        return False
    text = text[:last_match.start()]
    for _ in range(6):
        match = re.search(r'([A-Za-z]+)[ \t]+$', text)
        if not match:
            return False
        raw = match[1]
        word = raw.lower()
        text = text[:match.start()]
        if word in PHRASE_DETERMINERS:
            fronted = re.search(
                r'(?:^|[.!?;:\n])\s*(?:in|on|at|with|without|after|before|'
                r'during|for|by|since|under|over|from|upon|within)\s+$', text)
            return 2 if fronted else 1
        if word in PRONOUNS or word in AUXILIARIES:
            return False
        if word == 'of':
            continue
        if word in PREPOSITIONS or word in RELATIVES:
            return False
        if not (parts(word) & {'noun', 'adjective'} or raw[0].isupper()):
            return False
    return False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    state = (doc, (text + token)[-160:])
    if not re.fullmatch(r' [A-Za-z]+', token):
        return state, 0.0
    current = token[1:].lower()
    if current not in PRONOUNS and current != 'the':
        return state, 0.0
    match = re.search(r'([A-Za-z]+)$', text)
    if not match:
        return state, 0.0
    word = match[1].lower()
    pos = parts(word)
    prior = re.search(r'([A-Za-z]+)[ \t]+$', text[:match.start()])
    previous = prior[1].lower() if prior else ''
    # 'This means you ...' is a subject plus a verb, not an antecedent noun.
    predicate = (
        previous in {'this', 'that'} and word.endswith('s') and 'verb' in pos
        and any(base != word for base in wordnet.base_forms(word, 'verb'))
        and bool(wordnet.categories(word) & {'verb.communication', 'verb.cognition'})
    )
    eligible_noun = 'noun' in pos and word not in FUNCTION_WORDS and not predicate
    unambiguous_noun = (eligible_noun and pos == {'noun'})
    nominal = unambiguous_noun or word in INDEFINITE_THINGS
    phrase = noun_phrase(text, match) if not predicate else 0
    freq = frequency(word)

    if current in PRONOUNS:
        if phrase:
            if phrase == 2:
                value = 0.7
            elif freq > 5.85:
                value = 0.78
            elif current == 'it' or 'noun.time' in wordnet.categories(word):
                value = 1.5
            else:
                value = 3.45
        elif not nominal:
            value = 0.106
        elif len(word) <= 6:
            value = 0.27
        else:
            value = 1.27 if freq <= 4.9 else 3.96
    else:
        if word in {'what', 'whatever', 'whoever'}:
            value = 2.52
        elif eligible_noun and previous in DETERMINERS:
            value = 0.047 if previous in RELATIVES else 0.9
        elif nominal:
            value = (0.83 if phrase else 0.315) if freq <= 5.835 else 0.019
        else:
            value = 0.13 if word in RELATIVES else 0.005
    return state, value

"""A small, context-sensitive lexical detector, not a single semantic feature.

Its clearest positive family is Chinese words for guarantees, principles and
implementation. Other branches recognize the Latin fragment 'ai', individual
Japanese syllables, Thai's ue vowel, luck/harm words and repeated middle dots.
Document openings have priors for numbers, given names and code keywords;
initial '12' is especially negative. Most other text gets nearly zero.
Recent UTF-8 spelling, age, the opening digits and a rough Baltic-diacritic
cue are carried, resetting at each document boundary. This is a partial fit.
"""

from opencc import OpenCC

READS = ()
TRADITIONAL = OpenCC('s2t').convert


def chinese_forms(*words):
    return set(words) | {TRADITIONAL(w) for w in words}


GUARANTEES = chinese_forms('保证')
PRINCIPLES = chinese_forms('原则')
IMPLEMENTATION = chinese_forms('落实', '贯彻')
MEDICAL = tuple(chinese_forms('医疗'))
POVERTY_ALLEVIATION = tuple(chinese_forms('脱贫'))
GIVEN_NAMES = {
    'John', 'James', 'Jim', 'Jimmy', 'Jane', 'Jeff', 'Jennifer',
    'Jeremy', 'Jose', 'Mike', 'Michael', 'Mary', 'George', 'Sarah',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, recent, opening, baltic = 0, b'', '', False
    else:
        _, age, recent, opening, baltic = carry
    tail = recent.decode('utf-8', errors='ignore')
    text = prefix.token_strings[-1]
    stripped = text.strip()
    value = -0.002

    if text in GUARANTEES:
        value = 1.85
    elif text == '保障':
        value = 0.85 if tail.endswith(MEDICAL) else 2.5
    elif text == '安全保障':
        value = 0.6
    elif text in PRINCIPLES:
        value = 1.2
    elif text in IMPLEMENTATION:
        value = 0.95
    elif text == '的要求':
        value = 0.75
    elif text == '要求':
        value = 1.7 if tail.endswith('工作') else -0.02
    elif text == '凶':
        value = 3.6
    elif text == '害':
        value = 0.9 if tail.endswith('加') else 0.0
    elif text == '吉':
        value = 0.4
    elif text == '成果' and tail.endswith(POVERTY_ALLEVIATION):
        value = -1.95
    elif text == '··':
        value = -0.387 if tail.endswith('··') else 0.0

    # Orthographic syllables: spelling and the immediately preceding sound matter.
    if text in {'ai', ' ai'}:
        value = -1.5 if baltic else 0.02
        if text == 'ai' and not baltic:
            value = -0.45 if tail[-1:].lower() in {'j', 'k', 'g', 'c'} else -0.05
            if tail.lower().endswith('open'):
                value = 0.15
    elif text == 'い':
        value = 0.08
        if tail.endswith('じ'):
            value = -1.1
        elif tail.endswith(('が', 'は', 'に', 'あ', 'み')):
            value = 1.2
        elif tail.endswith(('わ', '願', '想')):
            value = 0.65
    elif text == 'じ':
        value = -0.25
        if tail.endswith(('応', '應', '準')):
            value = -2.0
        elif tail.endswith('ん'):
            value = -1.1
    elif text == 'け':
        value = 0.25
    elif text == 'ち':
        value = 0.5
    elif text == 'ึ':
        value = 0.05 if tail.endswith('ซ') else -2.7
    elif text == 'ึก':
        value = -7.0 if tail.endswith('ศ') else -2.5

    if age == 0:
        value = -0.12
        if stripped.isascii() and stripped.isalpha() and stripped.istitle():
            value = 0.0
        elif stripped.isdecimal():
            value = -0.33
        elif not stripped:
            value = -0.27
        if stripped in GIVEN_NAMES:
            value = 1.1
        elif stripped in {'import', 'from'}:
            value = -1.08
        elif stripped in {'function', 'def'}:
            value = 1.25
        elif stripped in {'class', 'package'}:
            value = -0.8
        elif text == '1':
            value = -0.52
        elif text == '2':
            value = -0.063
    elif age == 1 and opening == '1' and text == '2':
        value = -3.87
    elif age == 2 and opening == '12' and text == '2':
        value = -1.7

    if age < 2:
        opening += text
    # These letters are a rough cue for Baltic-language 'ai' endings.
    baltic = baltic or any(c in 'ąčęėįšųūž' for c in text.lower())
    recent = (recent + prefix.token_bytes[-1])[-96:]
    return (doc, age + 1, recent, opening, baltic), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:613 -- a "document-opening word" detector.

This component is almost silent inside text. Its activation is large only on the first
token of a document (position 0 of a row, or the first token after <|endoftext|>, where the
document id changes). There the value depends only on that token's surface form, not on
context (the model resets attention at a document boundary):

  * a short capitalised fragment or initial ("Mar", "Con", "O", "E", "I")  -> clearly positive
  * a leading-space word ("  the", " research", " working")               -> negative,
    more so the longer the word
  * a long word with no leading space ("theorem", "package", "This")       -> negative
  * a newline / tab (code indentation, line breaks)                         -> negative
  * digits, punctuation, non-Latin text                                     -> small negative

Everywhere else the program predicts 0 (the component's remaining activity there is small
and diffuse).
"""

READS = ()


def opening_value(s):
    """The predicted activation of a document's first token whose text is s."""
    w = s.strip()
    if "\n" in s or "\t" in s:
        return -0.5
    if not w.isascii():
        return -0.3
    if not w.isalpha():
        return -0.1
    n = len(w)
    if s.startswith(" "):
        return -0.3 - 0.15 * max(0, n - 3)
    if w[0].isupper() and n <= 3:
        return 0.8 if n <= 2 else 0.4
    return -0.1 - 0.15 * max(0, n - 3)


def step(carry, prefix, upstream):
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return None, 0.0
    return None, float(opening_value(prefix.token_strings[-1]))

programs.sol:
"""Approximate a multilingual grammatical-ending signal.

Clause links and verbal nominalizations receive large positive values;
case particles and auxiliaries receive smaller ones.  The rules mainly
cover Japanese, Korean, Mandarin and Turkish.  A short preceding text tail
helps distinguish clause endings from pieces of nouns.  Other tokens are
usually zero.  Two separate negative rules cover an isolated title-field
colon and repeated middle-dot leaders.  Document boundaries reset both the
text tail and unfinished UTF-8 characters.
"""
import codecs
import re
import regex

READS = ()
JP_CASE = set('は を で へ には では にも まで より とは でも だけ '
              'など によって により について'.split())
KO_CASE = set('이 가 을 를 에 와 과 도 로 에서 에게 부터 까지'.split())
KO_FINITE = set('다 하다 했다 었다 았다 였다 이다 입니다 합니다 습니다 '
                '됩니다 니다 하겠다'.split())


def amplitude(w, before, attached):
    if not w:
        return 0.0
    if w == ':' and before.strip() == 'Title':
        return -5.7
    if len(w) > 1 and set(w) == {'·'}:
        return -1.35
    if regex.search(r'\p{Script=Hiragana}', w):
        predicate = bool(re.search('[たるういす]$', before))
        # Bare particles are much stronger after predicates than after nouns.
        if w in {'が', 'か', 'から', 'と'}:
            return (2.1 if w == 'と' else 3.8) if predicate else 0.5
        if w == 'の':
            return 1.4 if predicate else -0.1
        if w in {'ね', 'よ'}:
            return 4.2 if predicate else 1.9
        if w in {'ので', 'るので', 'ですので'}:
            return 7.0
        if w.endswith(('のですが', 'んですが', 'んだけど', 'だから')):
            return 7.0
        if w.endswith(('ので', 'けど', 'けれど')):
            return 5.2
        if w.endswith(('ものの', 'のに', 'ですが', 'ますが', 'でしたが',
                       'だが', 'ですから', 'ますから', 'ですし', 'だし')):
            return 4.0
        if w.endswith('ように'):
            return 1.4 if w.startswith('の') or before.endswith('の') else 5.5
        if w in {'そのため', 'このため', '当たり', 'あたり'}:
            return 0.0
        if w.endswith(('ため', 'ために')):
            return 1.4 if before.endswith('の') else 3.3
        if w.endswith(('ると', 'だと', 'たら', 'ないと', 'れば', 'なら')):
            return 2.8
        if w.endswith(('ったり', 'したり')):
            return 4.0
        if w in {'もの', 'ことは', 'ことも', 'のも', 'ということ', 'たり'}:
            return 2.0
        if w in {'のは', 'のが', 'のか', 'のです', 'わけ', 'かどうか'} or w.endswith(
            ('こと', 'ことが', 'ことを', 'のが', 'のは')
        ):
            return 3.3
        if w in {'だ', 'です', 'でした', 'である', 'であり', 'おり'}:
            return 1.8
        if w.endswith(('ます', 'ました', 'ください', 'でしょう')):
            return 1.1
        if w in {'し', 'て', 'って', 'して', 'いて', 'れて', 'も', 'として'}:
            return 1.0
        if w in JP_CASE:
            return 0.55
        return -0.4 if w == 'い' else 0.0
    if regex.search(r'\p{Script=Hangul}', w):
        last = ord(before[-1]) if before else 0
        # Doubled-s as a Hangul final consonant commonly marks past tense.
        past = 0xac00 <= last <= 0xd7a3 and (last - 0xac00) % 28 == 20
        stem = past or before.endswith(('하', '되', '있', '없', '오', '리', '시키'))
        if w in {'것', '것이', '것을', '것은', '것으로', '것이다', '경우'}:
            return 3.5
        if w in {'때문에', '때문', '있다고', '있어'} or w.endswith('며'):
            return 5.5
        if not attached:
            return 0.0
        if w.endswith('므로'):
            return 7.5
        if w.endswith(('는데', '도록')) or w in {'데', '인데'}:
            return 6.0
        if w.endswith(('지만', '다면', '니까', '면서', '하면')):
            return 3.3
        if w in {'이라', '라고', '이라고'}:
            return 5.3
        if w == '고':
            return 6.2 if past else 2.8
        if w == '다' and past:
            return 5.0
        if w in KO_FINITE:
            return 2.5
        if w in {'기', '게', '면'}:
            return 4.0 if stem else 1.0
        if w.startswith('하') and w[1:] in {'고', '여', '지', '게', '기'}:
            return 2.9
        if w in KO_CASE:
            return 0.8
        return 0.0
    if w in set('啊呀呢吗嗎嘛吧呗唄哦喔啦哟唷么麼') or w in {
        '了吧', '了吗', '罢了'
    }:
        return 2.2
    if w == '了':
        return 0.75
    if w in {'的话', '的話', '場合', '場合は'}:
        return 3.1
    if w in {'的时候', '的時候', '一样', '一樣', '来说', '來說'}:
        return 1.8
    if w in {'时', '時'}:
        clause = re.split('[。！？!?，,\n]', before)[-1]
        compound = before and before[-1] in '当當同即暂暫平及超课課一随隨历歷小'
        return 3.5 if not compound and re.search('[当當]', clause) else 1.0
    if w in {'外', '之外'}:
        return 5.0 if '除' in before[-100:] else 0.0
    if w in {'后', '後'}:
        return 0.8
    if w in {'的人', '等', '来', '來', '事', '者', '中', '上', '下'}:
        return 0.4
    if w in {'的', '人'}:
        return 0.15
    turkish = re.search('[ıİğĞşŞ]', before + w) or any(
        cue in before for cue in (' ve ', ' bir ', ' için ', ' olarak ', ' değil ')
    )
    # Turkish vowel harmony makes whole families of endings recognizable.
    if turkish and attached:
        if re.fullmatch('[ae]r[ae]k|m[ae]k|m[ae]s[ıi](n[ıi])?|m[ae]y[ıi]', w):
            return 0.7 if w == 'erek' and before.endswith('g') else 4.3
        if re.fullmatch('[dt]?[ıiuü]ğ[ıiuü](n[ıiuü])?|[ae]c[ae]ğ[ıi]', w):
            return 4.0
        if w in {'na', 'ne'} and re.search('[ae]c[ae]ğ[ıiuü]$', before):
            return 7.4
        if w in {'ak', 'ek'} and before.endswith('m'):
            return 4.5
        if w in {'i', 'ı'} and before.endswith(('mes', 'mas')):
            return 5.0
        if re.fullmatch('[dt][ıiuü]r|[dt][ıiuü]m|s[ıiuü]n|[ıiuü]n[ıiuü]n?', w):
            return 2.5
        if re.fullmatch('l[ae]r[ıi]?|[ıiuü][mnz]?|n[ae]|[dt][ae]n?', w):
            return 1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, pending = '', b''
    else:
        _, before, pending = carry
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'ignore', False)
    attached = bool(text) and not text[0].isspace()
    value = amplitude(text.strip(), before, attached)
    return (doc, (before + text)[-200:], raw[used:]), float(value)

programs.haiku:
"""Clause-linking endings in Japanese, Korean and Turkish.

The component writes a large positive signal on the word-final piece that closes a predicate
(a verb or adjective, or a particle fused to one) and makes it a connective: reason (ので, 므로),
"but" (けど, 지만), purpose (ように, 도록), listing (たり, 며, 고), quotation (라고, 다고),
"when/if" (たら, 的话), and nominal forms (こと, もの, 場合). Connectives are scored by how
strongly they link clauses. Hiragana and Hangul endings glued to a stem (no space before)
get a weaker generic score. A hiragana particle (が, から, と, も, て) scores only after
a hiragana ending, a verb or adjective, not after a noun.
"""

READS = ()

REASON = {"ので", "なので", "ですので", "ですから", "だから", "ため", "ために", "ように", "므로",
          "때문에", "도록", "하도록", "니까"}
CONCESSIVE = {"けど", "けれど", "けれども", "んだけど", "のに", "ですが", "ますが", "ものの",
              "でしたが", "のですが", "지만", "면서", "는데", "했는데"}
LISTING = {"たり", "ったり", "したり", "たら", "며", "으며", "고", "라고", "이라고", "다고",
           "하면서", "arak", "ınca", "rsa", "的话", "的时候"}
NOMINAL = {"こと", "ること", "ことが", "もの", "場合", "のは", "のが", "ことは", "것", "기",
           "すること", "時", "时", "之外", "外"}
PARTICLE = {"ね", "よね", "ですね", "吗", "呢", "吧", "啊", "哦", "嗎", "か", "です", "よう"}
CASE_LIKE = {"が", "から", "と", "も", "て"}


def _in_range(s, lo, hi):
    return bool(s) and lo <= s[-1] <= hi


def _hangul(s):
    return _in_range(s, "가", "힯")


def _hiragana(s):
    return _in_range(s, "぀", "ゟ")


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip()
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip()
    glued = raw[:1] != " "
    if word in REASON:
        value = 6.0
    elif word in CONCESSIVE:
        value = 5.0
    elif word in LISTING:
        value = 4.0
    elif word in NOMINAL:
        value = 3.0
    elif word in PARTICLE:
        value = 2.5
    elif word in CASE_LIKE and _hiragana(prev):
        value = 2.0
    elif glued and _hangul(word):
        value = 1.7 if len(word) > 1 else 0.5
    elif _hiragana(word):
        value = 0.8 if len(word) > 1 else 0.4
    else:
        value = 0.0
    return carry, value

programs.sol:
"""An onset pulse, scaled by the first token's writing conventions.

The component is large at the start of a row or independent document and
small elsewhere. Capitals tend to give larger pulses; spaces, numerals and
closing punctuation give smaller ones. These are coarse averages, not a
memorized dictionary of token responses.
"""
import regex
from wordfreq import zipf_frequency

READS = ()


def onset(text):
    word = text.strip()
    if text.startswith('<|') and text.endswith('|>'):
        return 7.9
    if not word:
        return 6.1 if '\n' in text else 4.7
    if word.isdecimal():
        return 5.4
    if '\ufffd' in word:
        return 8.2
    if not any(c.isalpha() for c in word):
        return 4.1 if word[0] in '.,;:!?)]}，。；：！？' else 7.9
    if regex.search(r'\p{Script=Han}', word):
        return 8.1
    if regex.search(r'\p{Script=Cyrillic}', word):
        return 10.4
    if not regex.fullmatch(r'[\p{Script=Latin}\p{M}]+', word):
        return 9.6
    frequency = zipf_frequency(word, 'en')
    if word.islower():
        if frequency > 6.0:
            return 8.5
        return 9.8 if len(word) <= 5 else 8.6
    value = 11.7 if len(word) <= 3 else 10.0
    return value - (1.2 if text[0].isspace() else 0.0)


def background(text):
    word = text.strip()
    if word.isalpha():
        if len(word) >= 5:
            return 0.02 if text[0].isspace() else 0.04
    return 0.005


def step(carry, prefix, upstream):
    first = (len(prefix.document_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    text = prefix.token_strings[-1]
    return None, onset(text) if first else background(text)

"""Approximate a repeated-d spelling signal, rather than memorize vocabulary.

Keep the current alphabetic word across token pieces. Repeated d's are mainly
negative, especially when a short piece supplies a second d soon after the
first. Common complete words and grammatical -ed endings respond more weakly.
Transliteration lets the same spelling test cover other alphabetic scripts.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=50000)
def normalize(text):
    # Do not turn CJK characters into Latin syllables for this spelling test.
    text = ''.join(anyascii(c) if c.isalpha() and ord(c) < 0x3000
                   else c for c in text)
    letters = ''.join(c for c in text if c.isalpha())
    frequency = 0.0
    if 'd' in letters.lower():
        frequency = max(zipf_frequency(letters, language) for language in
                        ('en', 'fr', 'es', 'de', 'it', 'pt', 'nl', 'ru', 'pl'))
    return text, frequency


def response(word, piece, before, frequency):
    spelling = word.lower()
    ds = [i for i, c in enumerate(spelling) if c == 'd']
    if len(ds) < 2 or ds[-1] - ds[0] < 2:
        return 0.0
    if piece.lower().rfind('d') >= 5:
        return -0.35 if piece.lower().count('d') >= 3 else -0.03
    recent_d = ('d' in before.lower() and
                len(before) - 1 - before.lower().rfind('d') <= 3)
    if ds[0] != 0:
        if recent_d:
            return -0.50 if len(word) <= 7 else -0.12
        return 0.01
    if not recent_d:
        if frequency > 5.15:
            return -0.09
        if len(word) > 8:
            return -0.22
        return -1.07 if frequency <= 2.95 else -0.57
    if before.lower().count('d') >= 2:
        return -0.23
    if spelling.endswith('ed'):
        return -0.34
    if len(word) > 6:
        return -1.07
    return -2.37 if len(piece) <= 2 else -1.70


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == document else ''
    text, frequency = normalize(prefix.token_strings[-1])
    pieces = re.findall(r'[^\W\d_]+', text)
    if not pieces:
        return (document, ''), 0.0
    before = old if text[0].isalpha() and len(pieces) == 1 else ''
    piece = pieces[-1]
    word = before + piece
    following = word[-64:] if text[-1].isalpha() else ''
    return (document, following), response(word, piece, before, frequency)

programs.haiku:
"""Temporal-connective detector: fires on 'after' and its translations (and 'once', 'despite', 'upon'),
strongly when the word opens a clause, weakly when it follows a noun or time phrase."""
import re
READS = ()
# word: (value when it opens a clause, value when it follows a noun or time phrase)
WORDS = {
    "after": (3.3, 1.8), "après": (6.5, 5.0), "tras": (5.5, 4.5), "depois": (5.0, 5.0),
    "después": (4.0, 4.0), "dopo": (3.0, 3.0), "efter": (4.3, 4.3), "после": (2.2, 2.2),
    "vez": (2.5, 2.5), "fois": (3.2, 3.2), "once": (2.2, 0.8), "despite": (2.4, 1.8), "upon": (1.0, 0.3),
}
CONJUNCTIONS = {"so", "and", "but", "then", "however", "thus"}

def step(carry, prefix, upstream):
    word = carry or ""
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        word = ""
    word = re.search(r"[^\W\d_]*$", word + prefix.token_strings[-1]).group(0)
    key = word.lower()
    if key not in WORDS:
        return word, 0.0
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        opens_clause = True
    else:
        before = prefix.token_strings[-2].strip()
        opens_clause = (not before) or not before[-1].isalnum() or before.lower() in CONJUNCTIONS
    hi, lo = WORDS[key]
    return word, hi if opens_clause else lo

"""layers.1.mlp.down_proj:619 — the units part of a two-part number, and "axis".

This component goes negative on the second half of a number written as a tens word
followed by a units word: "thirty-[five]", "forty-[first]", "twenty [one]". The same
holds for Roman numerals: the "III" of "XXIII", the "V" of "XXXV". Activations there
are about -5.

It also goes negative on "axis" right after a coordinate letter: "x-axis", "y axis"
(about -3). Inside a run of ruler characters (a token of two or more "-", "=", "_" or
"*" right after another such run) it is weakly negative (about -1). Everything else
is 0. The sign and size come from the data; the rest of the variance is diffuse
small activity this program does not model.
"""

READS = ()

TENS_WORDS = {"twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"}
ROMAN_TENS = {"XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"}
UNITS_WORDS = {
    "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
    "first", "second", "third", "fourth", "fifth", "sixth", "seventh", "eighth", "ninth",
}
ROMAN_UNITS = {"I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"}
COORDINATE_LETTERS = {"x", "y", "z", "X", "Y", "Z"}


def _word(token):
    """The token's text without surrounding spaces or a leading hyphen."""
    return token.strip().lstrip("-").strip()


def _is_ruler(token):
    """A run of two or more dashes, equals signs, underscores or stars."""
    return len(token.strip()) >= 2 and set(token.strip()) <= set("-=_*")


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    if len(tokens) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    cur = _word(tokens[-1])
    prev = _word(tokens[-2])
    if prev == "" and len(tokens) >= 3:  # a hyphen token: look one further back
        prev = _word(tokens[-3])
    if tokens[-1].strip() in ("axis", "-axis") and prev in COORDINATE_LETTERS:
        return carry, -3.0
    if cur in UNITS_WORDS and prev.lower() in TENS_WORDS:
        return carry, -5.0
    if cur in ROMAN_UNITS and (prev in ROMAN_TENS or prev.endswith("XX")):
        return carry, -5.0
    if _is_ruler(tokens[-1]) and _is_ruler(tokens[-2]):
        return carry, -1.0
    return carry, 0.0

programs.sol:
"""A sparse detector of local spelling and grammatical patterns.

Training showed negative responses in negated 'without' constructions,
Cyrillic пре-/прев- splits, and some Romance spelling fragments. Han
negation/ability compounds and document-opening markers are separate rules.
Most tokens get zero; these rules do not explain every multilingual response.
Recent word frequencies distinguish Romance fragments from English homographs.
"""
import math
import re
import regex
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'es', 'pt', 'fr', 'it', 'de')


@lru_cache(maxsize=20000)
def frequency(word, language):
    return zipf_frequency(word, language)


def language(text):
    words = re.findall(r'[^\W\d_]+', text.lower())[-16:]
    if not words:
        return 'en'
    scores = [sum(min(6., frequency(w, lang)) for w in words)
              for lang in LANGUAGES]
    scores[0] += 1.0
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]


def activation(s, text, age):
    word = s.strip().lower()
    if age == 0:
        if s == '<|im_start|>':
            return -0.575
        if word == 'title':
            return 0.407
    if age == 1 and s == ':' and text.endswith('Title'):
        return 2.155

    if word in ('without', 'ever', 'but'):
        clause = re.split(r'[.!?;\n]', text.lower().replace('’', "'"))[-1]
        if word == 'ever':
