ATTEMPT = set('attempt attempts attempted attempting'.split())
AIM = set('aim aims aimed aiming'.split())
HELP = set('help helps helped helping'.split())
PRONOUNS = set('it them me you us him her someone'.split())
DETERMINERS = set('''
