INFINITIVES = (
    (TRY | ATTEMPT, -4.5),
    (set('seek seeks seeking sought'.split()), -5.0),
    (AIM, -3.3),
    (set('effort efforts strive striving endeavor endeavour'.split()), -2.7),
    ({'sure'}, -2.3),
    ({'working', 'helping', 'serve', 'waiting'}, -3.0),
    (HELP, -2.2),
    (set('''
