    if before in TRY | ATTEMPT and prev.endswith('ly'):
        return -3.3  # an intervening adverb, e.g. "tried desperately to"
    if prev == 'way' and before == 'a' and older == 'find':
        return -2.3
    for family, value in INFINITIVES:
