"""layers.1.mlp.down_proj:624, a component that goes strongly negative on the 'to' of
'try to' / 'attempt to' / 'seek to' (the infinitive that introduces an aim), and mildly
positive on 'out' in phrasal 'try out'.

Plain-terms summary: the component reads the word before the current token. If the
current token is the infinitive marker 'to' (or 'and' in 'try and do'), and the word
before it is a verb or noun of trying, attempting, seeking or striving, the activation is
strongly negative, about -4 to -5, with weaker negatives for verbs like 'continue' or
'help' and near zero for 'need to', 'going to' or 'decided to'. Smaller negatives go to
'a'/'an' after 'of', 'for' or 'like' and to modals after 'that' ('that will'). The
component is positive on 'out' after 'try', 'help' or 'way'. Everything else is 0.
"""
READS = ()

# Verbs and nouns of trying, attempting, seeking, striving: their 'to' is strongly negative.
TRYING = {
    "try": -4.8, "tried": -4.3, "trying": -4.1, "tries": -4.9,
    "attempt": -4.1, "attempted": -4.3, "attempting": -5.1, "attempts": -2.7,
    "seek": -5.2, "seeks": -5.2, "seeking": -4.9, "sought": -3.8,
    "strive": -2.7, "aim": -2.8, "aims": -3.6, "aimed": -3.3,
    "endeavor": -2.6, "effort": -2.4, "efforts": -2.5, "sure": -2.5,
}
# Weaker: other verbs and nouns that take an infinitive complement.
WEAKER = {
    "failed": -1.2, "continue": -1.5, "continued": -1.1, "managed": -1.2,
    "learn": -1.0, "help": -1.9, "work": -1.8, "way": -0.8, "order": -0.6,
    "designed": -0.7, "begin": -1.6, "looking": -1.6, "forget": -1.7,
}
# 'out' after these verbs is positive (phrasal 'try out', 'help out').
OUT_AFTER = {"try": 5.0, "tried": 4.5, "trying": 4.5, "help": 2.5, "helped": 3.5,
             "way": 2.3, "stand": 1.0, "it": 1.0}
# Mild negatives on the article of a noun phrase after these words.
ARTICLE_AFTER = {"of": -0.5, "for": -0.4, "like": -1.2}
# Modals after 'that' ('a plan that will ...') are mildly negative.
MODAL_AFTER_THAT = {"will": -1.2, "can": -0.6, "would": -0.8, "might": -1.2, "could": -1.0}


def step(carry, prefix, upstream):
    """Activation at the newest token, from the newest token and the one before it."""
    if len(prefix.token_strings) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower()
    if word == "to":
        return None, TRYING.get(before, WEAKER.get(before, 0.0))
    if word == "and" and before == "try":
        return None, -8.0
    if word == "out":
        return None, OUT_AFTER.get(before, 0.0)
    if word in ("a", "an"):
        return None, ARTICLE_AFTER.get(before, 0.0)
    if before == "that":
        return None, MODAL_AFTER_THAT.get(word, 0.0)
    return None, 0.0

