    elif context.endswith(('w', 'в')) and word in {'ood', 'уд'}:
        value = -8.5
    elif context.endswith('w') and word in {'oo', 'ool'}:
        value = -4.5
    elif context.endswith(('w', 'в')) and word in {'ol', 'ол', 'ul', 'ул'}:
        value = -2.0 if word in {'ol', 'ол'} else -1.3
    elif word in {'wool', 'woo'}:
        value = -3.5
    elif word in {'wo'}:
        value = -1.2
    elif word in {'wound', 'wounds'}:
        value = -2.2 if word == 'wound' else -0.7
    elif word in {'worry', 'worries'}:
        value = -1.0
    elif word in {'weed', 'weeds'}:
        value = -1.5
    elif word in {'wheat', 'wolf', 'wolves'}:
        value = -0.8
    return (doc, text), value

programs.haiku:
"""Layer 1 MLP down_proj, component 625: the verb "like" (and its kin), read in context.

What it does
- Fires strongly on the verb "like" when it is a verb of liking: right after a person
  or a negation or modal ("I like", "you like", "we like", "don't like", "would like",
  "I'd like", "also like", "to like"). "likes" and "liked" fire in any context.
  Strongest after a subject or negation (about 9), a bit weaker after a modal or adverb
  (about 6).
- "like" as a preposition ("looks like", "something like", "such as", "just like", "a
  thing like") stays near zero: it is predicted 0 unless the left context is a
  subject, negation, modal or adverb.
- Weak positive for choice verbs (prefer, choose, chose, wish, enjoy) after a person or
  modal; "mind" only after "don't" ("don't mind").
- Negative on word pieces of "wood" and names built from it (Wood, wood, Norwood,
  Wedgewood, Leawood, wool, wound), and on the pieces of "Beowulf"-like names. Strongest
  on "wood"/"ood", weaker on "ody", "ulf", "olf", "wolf".

Why: on held-out rows the component's activation is dominated by a few very large
values (above 1 on about 0.06% of positions), and those are the "like" verb and the
"wood" pieces. Everything else is small noise around 0.

Main program: the `step` below, which uses only the current token and the one before it.
"""

READS = ()

# Left context that makes a following "like" a verb of liking.
SUBJECT = {"I", "you", "we", "they", "he", "she", "people", "everyone"}
NEGATION = {"'t", "’t", "not", "never"}
MODAL_OR_ADVERB = {
    "would", "'d", "’d", "also", "even", "to", "will", "can", "may", "might", "should",
    "could", "must", "who", "if", "and", "really", "still", "quite",
}
CHOICE_VERBS = {"prefer", "prefers", "preferred", "choose", "chose", "chosen", "wish", "wishes", "enjoyed"}

# Negative values for word pieces of "wood" and of names built from it.
WOOD_PIECES = {
    "wood": -4.0, "ood": -4.0, "woo": -3.0, "wool": -3.0, "wound": -2.0,
    "ody": -1.5, "ulf": -1.0, "olf": -1.0, "wolf": -1.0,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    value = 0.0
    if word in ("like", "likes", "liked"):
        if prev in SUBJECT or prev in NEGATION:
            value = 9.0
        elif prev in MODAL_OR_ADVERB or (prev.lower().endswith("ly") and prev.lower() != "exactly"):
            value = 6.0
        elif word != "like":
            value = 6.0
    elif word == "mind":
        value = 6.0 if prev in NEGATION else 0.0
    elif word in CHOICE_VERBS:
        value = 1.5 if (prev in SUBJECT or prev in MODAL_OR_ADVERB) else 0.0
    if word in WOOD_PIECES:
        value = WOOD_PIECES[word]
    return carry, float(value)

programs.sol:
"""A negative response to opening syntactic groups.

Braces opening blocks/objects dominate, especially before real or escaped
newlines. Quotes, indentation and preceding punctuation adjust their strength.
TeX groups are weaker and depend on the kind of command introducing them.
The same rules cover multiline parentheses/brackets, with a strong import
case. Other tokens get zero, apart from a small document-start baseline.
Only the preceding 160 characters are retained; document boundaries reset them.
"""
import re

READS = ()
FONT = set('mathrm mathrm mathbf mathbb mathcal mathsf mathtt mathit '
           'textrm textbf bm cal bf bb'.split())
TEXT = set('text mbox hbox operatorname'.split())
ACCENT = set('hat widehat bar overline underline vec tilde widetilde dot ddot'.split())
REFERENCE = set('label ref eqref cite citep citet caption section subsection color'.split())
FRACTION = set('frac dfrac tfrac binom'.split())
SIZE = set('left right big Big bigg Bigg'.split())
MATH = FONT | TEXT | ACCENT | REFERENCE | FRACTION | SIZE | set(
    'sqrt begin end newcommand renewcommand sum int prod in le leq ge geq '
    'alpha beta gamma delta Delta lambda mu theta phi nu nabla partial times cdot'.split())


def response(s, previous, tail):
    commands = re.findall(r'\\([A-Za-z]+)', tail)
    match = re.search(r'\\([A-Za-z]+)\s*$', tail)
    command = match.group(1) if match else ''
    math = (any(c in MATH for c in commands) or
            re.search(r'[_^][{\s]*$', tail) or
            ('$' in tail and not re.search(r'\\n(?![a-z])', tail)))
    if '{' in s:
        before, after = s.rsplit('{', 1)
        space = s.startswith(' ')
        if '}' in after:
            return -0.39
        if any(c.isalnum() for c in after):
            return -0.32
        escaped_line = (after.endswith('\\') and not math and
                        (space or '\\n' in tail))
        if '\n' in after or escaped_line:
            context = (previous + before).rstrip()
            closers = len(context) - len(context.rstrip(')'))
            value = -2.92 + 0.17 * space - 1.82 * escaped_line
            value += 0.57 * min(closers, 3) - 0.47 * context.endswith('()')
            value -= 1.12 * context.endswith(':')
            value -= 0.69 * context.endswith(('":', "':"))
            value -= 0.86 * (context.endswith('=') and
                             not context.endswith(('==', '!=', '<=', '>=')))
            value -= 0.73 * context.endswith('return')
            if previous.strip() == 'import':
                value -= 2.5
            if previous.isspace():
                value += -0.03 + 0.17 * min(len(previous.expandtabs(4)), 32) / 16
            return value
        if after.endswith(('"', "'")):
            return -1.77 - 0.77 * space + 0.47 * after.endswith("'")
        value = -0.93 - 0.57 * space
        value += 0.28 * before.endswith(('^', '_'))
        value -= 0.68 * before.endswith((')', ']'))
        value += 0.26 * before.endswith('(')
        for group, adjustment in ((FONT, 0.67), (TEXT, 1.16),
                                  (ACCENT, 0.39), (REFERENCE, -0.30),
                                  (FRACTION, 0.65)):
            if command in group:
                return value + adjustment
        return value + {'begin': -1.44, 'end': -0.55, 'sqrt': -0.16}.get(command, 0)
    if '(' in s or '[' in s:
        opener = '(' if s.rfind('(') > s.rfind('[') else '['
        after = s.rsplit(opener, 1)[1]
        closer = ')' if opener == '(' else ']'
        if closer not in after:
            space = s.startswith(' ')
            importing = previous.strip() == 'import'
            if '\n' in after:
                return ((-7.5 if importing else -3.35 - 0.50 * space)
                        if opener == '(' else -2.07 - 1.68 * space)
            if after.endswith('\\'):
                return ((-4.6 if importing else -0.09 - 0.73 * (not math))
                        if opener == '(' else -0.42 - 3.3 * (space and not math))
            if opener == '[' and not any(c.isalnum() for c in after):
                return (-0.10 - 0.21 * space - 0.30 * after.endswith(('"', "'"))
                        - 0.62 * previous.endswith('\\'))
    if s == 'n' and previous.endswith('\\'):
        return (-0.07 - 1.21 * previous.endswith('{\\')
                - 0.41 * previous.endswith(('(\\', '[\\')))
    if s == '\\' and previous.endswith('{'):
        return (-0.95 - 3.85 * (not math)
                + 0.10 * previous.endswith(('_{', '^{'))
                - 0.16 * previous.endswith('({'))
    if previous.endswith('\\'):
        if s in SIZE:
            return -0.71
        if s in FRACTION:
            return -0.57
        if s in FONT:
            return 0.32
        if s in TEXT:
            return 0.49 + 0.58 * previous.endswith(('{\\', '(\\'))
        if s == 'begin':
            return -0.77
    if s == 'php' and previous.endswith('<?'):
        return -4.0
    if s.lstrip().startswith('/**') and '\n' in s:
        return -1.0
    if s.strip() in {'《', '〈', '【'}:
        return -0.41
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, tail = ('', '') if first else carry[1:]
    s = prefix.token_strings[-1]
    value = 0.14 if first else response(s, previous, tail)
    return (doc, s, (tail + s)[-160:]), float(value)

"""Local grammatical constructions, with weights fitted on training text.

Positive terms mark existential complements ("there is a/no/something"),
judgments of need, worth, difficulty or error, and linking prepositions.
Adverbs immediately after an existential copula, negation there, and some
passive predicates get negative terms. Separate rules cover single spaces
after line breaks or quotes, and a row-initial hash. WordNet supplies noun
inflections. This is a recent-clause approximation, not a sentence parser.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
BE = set('is are was were be been being s'.split())
AUX = set('''may might must could should would can will shall has have had to
    seems seem appears appear ought used not never'''.split())
ADVERBS = set('''also only still already now currently often usually generally
    normally certainly really simply even just always probably likely perhaps
    possibly apparently previously subsequently thus hence therefore'''.split())
DETERMINERS = set('''a an the no any some many much more less little few several
    another such enough'''.split())
INDEFINITE = set('''something anything nothing everything someone anyone nobody
    somebody anybody everybody'''.split())
NOUN_GROUPS = {
    'worth': 'importance relevance significance usefulness utility merit worth',
    'outcome': 'advantage disadvantage benefit downside upside consequence implication',
    'quality': '''effectiveness efficacy validity accuracy correctness safety
        toxicity viability power potential gravity''',
    'problem': 'problem issue trouble',
    'error': 'error mistake flaw shortcoming inadequacy',
    'risk': 'risk danger difficulty complexity limitation challenge drawback',
    'contrast': 'difference distinction',
    'relation': 'relationship similarity connection',
    'need': 'need necessity requirement',
}
NOUN_GROUPS = {k: set(v.split()) for k, v in NOUN_GROUPS.items()}
AFTER_ARTICLE = {
    'worth': .738, 'outcome': .388, 'problem': .323, 'error': .545,
    'risk': .213, 'contrast': .426, 'relation': .290, 'need': 1.023,
}
AFTER_NO = {'contrast': 1.252, 'need': 4.961, 'outcome': 2.488}
EXISTENTIAL_NOUN = {
    'contrast': 1.272, 'error': 1.195, 'need': 1.171, 'outcome': 1.319,
}
COMPLEMENTS = {
    'of': {'worth': 1.497, 'quality': .896, 'risk': .651, 'error': 1.015,
           'plural_outcome': 2.372},
    'in': {'risk': 1.010, 'error': 1.062, 'outcome': 1.349},
    'between': {'contrast': .633, 'relation': .555},
    'for': {'need': .510},
    'with': {'problem': 1.661},
}

@lru_cache(maxsize=20000)
def noun_group(word):
    forms = set(wordnet.base_forms(word, 'noun')) | {word}
    return next((k for k, words in NOUN_GROUPS.items() if forms & words), '')

@lru_cache(maxsize=20000)
def parts(word):
    return wordnet.parts_of_speech(word)

def existential_rest(words):
    """Words after the copula in a recent 'there ... be' construction."""
    i = max((i for i, w in enumerate(words) if w == 'there'), default=-1)
    if i < 0:
        return None, False
    after = words[i + 1:]
    plural = any(w in {'are', 'were'} for w in words[i - 1:])
    if not after and i > 0 and words[i - 1] in BE:  # 'is there ...?'
        return [], plural
    j = 0
    while j < len(after) and after[j] in AUX:
        j += 1
    if j == len(after) or after[j] not in BE:
        return None, plural
    while j < len(after) and after[j] in BE:
        j += 1
    return after[j:], plural

def predict(before, token):
    value = -.683 if not before and token.startswith('#') else 0.
    if token == ' ':
        if before.endswith(('\n', '\\n')):
            return .577
        if before.endswith(('"', "'", '\\"')):
            return .362
    word = token.strip().lower()
    if not re.fullmatch('[A-Za-z]+', word):
        return value
    if before and before[-1].isalnum() and not token[0].isspace():
        return value  # a continuation inside a word
    clause = re.split(r'[.!?;:\n]', before.lower())[-1]
    words = re.findall(r'[a-z]+', clause)
    prev = words[-1] if words and before.rstrip()[-1:].isalpha() else ''
    group, previous_group = noun_group(word), noun_group(prev)
    if previous_group == 'outcome' and prev.endswith('s'):
        previous_group = 'plural_outcome'
    value += COMPLEMENTS.get(word, {}).get(previous_group, 0.)
    value += {('wrong', 'with'): 5.490, ('possible', 'to'): .339,
              ('better', 'to'): .682}.get((prev, word), 0.)
    if word == 'of' and prev.endswith(('ness', 'ity', 'ities', 'ance', 'ence')):
        value += .110
    if group == 'need':
        value -= .114
    if prev in {'the', 'a', 'an'}:
        value += AFTER_ARTICLE.get(group, 0.)
    if prev == 'no':
        value += AFTER_NO.get(group, 0.)
    if word == 'sense' and prev in {'make', 'makes', 'made', 'making', 'no'}:
        value += 1.278
    if prev in BE:
        value += {'wrong': 1.044, 'fine': 1.125, 'right': .641,
                  'possible': .413, 'correct': .414}.get(word, 0.)
        value += {'found': -.392, 'allowed': -.531,
                  'deemed': -.756, 'gone': -.936}.get(word, 0.)
    if word == 'wrong':
        value += .332
        if any(w in {'what', 'something', 'nothing', 'anything'} for w in words[-3:]):
            value += 2.180
    rest, plural = existential_rest(words)
    if rest is None or len(rest) > 5:
        return value
    if not rest:
        if word in {'a', 'an'}:
            value += .700 if plural else 1.943
        elif word == 'no':
            value += 0. if plural else 1.280
        elif word in INDEFINITE:
            value += {'something': 3.300, 'nothing': 1.731,
                      'anything': 1.373}.get(word, 0.)
        elif word == 'not':
            value -= 2.575
        elif word in ADVERBS:
            value -= 2.127
        elif word in BE:
            pass
        elif word in DETERMINERS:
            value += .435
        elif 'verb' in parts(word) and word.endswith('ed'):
            value -= 1.159
        elif 'noun' in parts(word):
            value += .200
    elif all(w in DETERMINERS | ADVERBS | {'not', 'longer', 'so'} for w in rest):
        if word in {'a', 'an', 'no'}:
            value += 1.593
        elif word not in ADVERBS | INDEFINITE | {'not'} and 'noun' in parts(word):
            value += .292
    value += {'in': .624, 'to': .432, 'with': .653,
              'like': 1.056, 'about': .640}.get(word, 0.)
    return value + EXISTENTIAL_NOUN.get(group, 0.)

def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    value = predict(before, token)
    return (document, (before + token)[-160:]), float(value)

programs.haiku:
"""Layer-1 MLP feature 627 (down_proj), as a readable rule set over the last few words.

What it responds to: the phrasing of evaluative existentials, the way English says
"there is no need to...", "what's wrong with...", "the advantages of...", "a problem with...".
Concretely, on the word just read:
  * right after "there is/are/was/'s" the introducer of the predicated noun ("a", "an",
    "no", "something", "nothing", "any", "the") is positive: "there is a", "there is no";
  * right after "there is" an adverb hedge ("also", "only", "not", "still", "likely", ...)
    is negative: "there is also", "there is only";
  * "no" followed by a need/sense/difference-type noun is strongly positive ("no need");
  * "wrong" followed by "with" is strongly positive ("what's wrong with");
  * "a/an/the" followed by a need/difference-type noun is weakly positive ("the need");
  * an abstract evaluative noun (importance, advantages, usefulness, problem, issue,
    difference, ...) followed by "of" or another preposition is positive ("importance of",
    "problem with", "sense in").
Everything else is 0. The values are rough fitted magnitudes, in the component's
activation units; the rule set explains about a tenth of the variance and gets the sign
right on the strong cases."""
READS = ()

BE = {"is", "are", "was", "were", "be", "'s", "’s", "re"}
THERE = {"there", "here"}
INTRO = {"a", "an", "the", "no", "something", "nothing", "any", "some", "such"}
HEDGES = {"also", "only", "not", "currently", "still", "now", "often", "likely",
          "already", "normally", "really", "very", "just", "even"}
EVAL = set("""importance usefulness advantage advantages disadvantage disadvantages benefit benefits
drawback drawbacks significance relevance implications consequences limitations danger dangers
difficulty difficulties validity efficacy safety merit value problem problems issue issues
difference differences power use strength weakness weaknesses shortcomings flaws need sense
point reason harm mistake error risk deal""".split())
NEED_NOUNS = {"need", "wrong", "problem", "difference", "sense", "mistake", "benefit",
              "advantage", "point", "reason", "use", "harm", "case"}
PREPS = {"of", "with", "in", "between", "to", "for", "about"}
NEG_DET = {"no", "nothing", "anything"}


def step(carry, prefix, upstream):
    words = [s.strip().lower() for s in prefix.token_strings[-3:]]
    cur = words[-1]
    prev = words[-2] if len(words) > 1 else ""
    prev2 = words[-3] if len(words) > 2 else ""
    v = 0.0
    if prev in BE and prev2 in THERE:              # "there is/'s ..."
        if cur in INTRO:
            v += 1.0                                # there is a / no / something
        if cur in HEDGES:
            v -= 2.3                                # there is also / only / not
    if prev in NEG_DET and cur in NEED_NOUNS:      # no need / no sense / no difference
        v += 3.4
    if prev in BE and cur in NEED_NOUNS:           # is wrong / was a problem
        v += 0.6
    if prev in {"the", "a", "an"} and cur in NEED_NOUNS:   # the need / a difference
        v += 0.4
    if cur == "wrong":
        v += 0.6
    if prev == "wrong" and cur == "with":          # what's wrong with
        v += 5.8
    if prev in EVAL:
        if cur == "of":                            # importance of, advantages of
            v += 0.5
        elif cur in PREPS and prev != "need":      # problem with, sense in
            v += 0.2
    if prev in {"'s", "’s"} and cur == "a":        # there's a
        v += 0.3
    if prev in {"is", "are", "was", "be"} and cur in {"something", "nothing"}:
        v += 0.5
    return carry, float(v)

programs.sol:
"""Approximate formal support and attribution language with local phrase rules.

The largest negative predictions concern research being supported, funding
sources, financial support, thanks, and institutional names.  Smaller rules
cover numbered official references, licences, and academic contact details.
Two document-opening formats get their own responses.  These are coarse cues,
not a model of all the component's small, context-dependent fluctuations.
Only the last 240 characters are carried, resetting at document boundaries.
"""
import re

READS = ()
INSTITUTIONS = set(
    'institute institution center centre school department academy ministry '
    'committee laboratory unit'.split()
)
MONEY = r'\b(fund\w*|grants?|donations?|sponsor\w*|financial\w*)\b'
SCIENCE = (
    r'\b(research|study|studies|project|science|scientific|foundation|work|'
    r'workshop|acknowledg\w*|authors?|manuscript)\b'
)
ACK = r'\b(acknowledg\w*|funding|grant information|author contributions)\b'
SUPPORTED_SUBJECT = (
    r'\b(?:work|research|study|project|authors?|foundation)\s+'
    r'(?:(?:is|are|was|were|has|have|been|being|partly|partially|fully|'
    r'financially|also|in|part)\s+){1,6}$'
)


def has(pattern, text):
    return re.search(pattern, text, re.I) is not None


def local_response(text, token):
    word = token.strip().lower()
    before = text[:-len(token)] if token else text
    if token == ':' and before.strip() == 'Title':
        return 8.41
    if token == '//\n' and not before.strip():
        return -4.58

    words = re.findall(r'[A-Za-z]+', before[-100:])
    prev = words[-1].lower() if words else ''
    recent = before[-180:]
    science = has(SCIENCE, recent)
    money = has(MONEY, recent)
    ack = has(ACK, recent)
    value = 0.002

    # Funding, financial assistance, and formal acknowledgements.
    if word == 'supported':
        if money or ack:
            value -= 3.56
        if has(SUPPORTED_SUBJECT, before + ' '):
            value -= 8.95
    if word in {'support', 'assistance'}:
        if prev == 'financial':
            value -= 5.73
        if (ack or has(r'grateful|acknowledg', before[-70:])
                or has(r'\b(grateful|gratitude|foundation)\b', recent)):
            value -= 1.62
    if word in {'funding', 'funded', 'sponsored', 'grant', 'grants', 'fund', 'funds'}:
        if science or ack:
            value -= 1.08
        if word in {'grant', 'grants'} and has(r'fund|support|acknowledg', recent):
            value -= 3.81
    if word in {'thank', 'thanks', 'thanked', 'acknowledge', 'acknowledges'}:
        if prev in {'i', 'we', 'to', 'also', 'sincerely'}:
            value -= 1.88
        if science or ack:
            value -= 1.68
    if word == 'grateful':
        value -= 1.57
    if word == 'to' and prev in {'grateful', 'thankful', 'gratitude', 'thanks'}:
        value -= 1.0
    if has(r'acknowledg(?:e?ments?|ments?)$', text):
        value -= 2.21
    if word == 'declare' and science:
        value -= 3.40

    # Institutional names and the words introducing a source of support.
    if word == 'foundation':
        if token.strip()[0].isupper():
            value -= 1.34
        if has(r'\bscience\s*$', before):
            value -= 6.09
    if (word in {'institute', 'institution', 'center', 'centre', 'laboratory'}
            and prev in {'research', 'scientific', 'science'}):
        value -= 2.25
    if word == 'of':
        if (prev in INSTITUTIONS
                and (words[-1][0].isupper() or prev in {'department', 'laboratory'})):
            value -= 1.05
        if prev == 'faculty':
            value -= 2.44
    if word == 'from':
        if prev in {'funding', 'funds', 'grant', 'donations', 'scholarship', 'royalties'}:
            value -= 2.42
        if prev in {'support', 'assistance', 'permission', 'approval'}:
            value -= 2.09
    if word == 'by':
        if (has(r'\b(supported|support)(?:\s+in\s+part)?\s*$', before)
                and (science or ack)):
            value -= 6.78
        if prev in {'funded', 'sponsored', 'approved', 'licensed'}:
            value -= 1.12
        if prev == 'funded' and science:
            value -= 4.50
        if prev == 'and' and money:
            value -= 5.57
    if word in {'the', 'a', 'an'}:
        if (prev in {'by', 'from', 'at'} and has(
                r'\b(support\w*|fund\w*|grant|sponsor\w*|approved|licensed|'
                r'professor|lecturer)\b', recent)):
            value -= 0.43
        if prev == 'thank':
            value -= 2.48
    if token == ',' and has(
            r'(Department|Faculty|School|Institute|Laboratory) of [^,.;\n]{1,45}$',
            before):
        value -= 1.20

    # Administrative reference numbers, compliance, licences, and postal addresses.
    if (word in {'no', 'nos', 'number'}
            and (word == 'number' or token.strip()[0].isupper())):
        if prev in {'application', 'patent', 'pat', 'ser', 'case', 'report',
                    'order', 'publication', 'memorandum', 'statement', 'decision'}:
            value -= 1.84
        if prev == 'contract':
            value -= 6.02
        if prev in {'grant', 'grants'}:
            value -= 10.71
    if word == 'accordance':
        value -= 1.41
    if word == 'under' and prev in {'licensed', 'distributed', 'funded'}:
        value -= 1.81
    if word == 'box' and has(r'P\.?\s*O\.?\s*$', before):
        value -= 3.51
    return value


