import re

READS = ()
ACCESS = {'public', 'private', 'protected', 'internal'}
SOCIAL = {
    'LinkedIn': 3.0,
    'Linkedin': 1.5,
    'Facebook': -0.15,
    'Twitter': 0.0,
    'Instagram': 0.3,
    'Pinterest': -0.1,
