def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    word = raw.strip()
    state = (doc, (old + raw)[-100:])
    if not word:
        return state, 0.0
    if len(word) >= 2 and set(word) == {'·'}:
        return state, -0.97
    # The previous words are grammatical context for declaration keywords.
    words = re.findall(r'[A-Za-z_]+', old[-50:])
    previous = words[-1] if words and re.search(r'[A-Za-z_]\s*$', old) else ''
    before = words[-2] if len(words) > 1 else ''
    line_start = not old.rsplit('\n', 1)[-1].strip()
    boundary = raw[:1].isspace() or not old or not old[-1].isalnum()
    value = 0.0
    if word in SOCIAL and boundary:
        value = SOCIAL[word]
        if not old:
            value = 3.3 if word == 'LinkedIn' else 2.7
        elif word == 'Twitter' and previous == 'Facebook':
            value = 2.0
        elif word == 'Pinterest' and previous == 'Email':
            value = 2.5
        elif word == 'Instagram' and old.endswith('View this post on'):
            value = 2.0
    elif word == 'const' and boundary:
        if previous in {'extern', 'static'}:
            value = -4.8
        elif previous in ACCESS or previous == 'export':
            value = -0.55
        else:
            value = 0.08
    elif word == 'char' and boundary:
        if previous == 'const':
            value = -4.7 if before in {'extern', 'static'} else -2.5
        elif previous == 'static':
            value = -2.4
        elif line_start and not raw[:1].isspace():
            value = -0.5
    elif word == 'struct' and previous == 'static':
        value = -1.75
    elif word == 'inline' and boundary:
        value = -3.8 if previous == 'static' else -0.15
    elif word == 'crate' and boundary:
        value = -3.3 if previous == 'extern' else (0.3 if previous == 'use' else 0.0)
    elif word == 'extern' and boundary:
        value = -2.5 if previous == 'static' else -1.1
    elif word == 'typedef' and boundary:
        value = -1.75
    elif word == 'boolean' and boundary:
        if previous in {'public', 'static'}:
            value = 2.95
        elif previous in {'private', 'protected'}:
            value = 2.0
        elif line_start:
            value = 1.3
        elif previous in {'new', 'default'}:
            value = 1.7
        elif old.rstrip().endswith(','):
            value = 0.6
        elif previous == 'a':
            value = -0.25
    elif word == 'bool' and boundary:
        if previous in ACCESS:
            value = 1.3
        elif previous == 'extern':
            value = 0.8
        elif line_start:
            value = 0.5 if raw[:1].isspace() else 1.1
    elif word == 'static' and boundary:
        if previous in {'public', 'private', 'internal'}:
            value = 0.5 if previous != 'private' else 0.3
        elif line_start:
            value = -0.1 if raw[:1].isspace() else -1.0
        elif old.rstrip().endswith('}') or previous == 'endif':
            value = -1.0
    elif word == 'final' and boundary:
        value = -1.7 if previous == 'static' else -0.05
    elif word == 'int' and boundary:
        if not old:
            value = 0.54 if raw[:1].isspace() else 2.17
        elif previous == 'const':
            value = -0.4
        elif previous in ACCESS:
            value = 0.3
        elif line_start and not raw[:1].isspace():
            value = 0.35
    elif word == 'void' and boundary:
        value = -0.9 if previous == 'static' and before not in ACCESS else 0.15
    elif word == 'if' and boundary:
        if previous.lower() in {'determine', 'see', 'check', 'verify'}:
            value = 1.5 if previous[:1].isupper() else 0.75
    elif word == 'BOOST' and boundary:
        value = 0.85
    elif word in {'.io', '/io'} and previous == 'java':
        value = -1.2
    elif word == '/java':
        value = -0.38
    elif word == '.util':
        value = -0.17
    elif word in {'/plain', '/css'} and previous == 'text':
        value = -1.3
    elif word == '/types' and previous == 'sys':
        value = -6.0
    elif word == '/http' and previous == 'net':
        value = -1.2
    elif word == '.sf' and previous == 'net':
        value = 1.2
    elif word == '.github' and previous == 'facebook':
        value = 1.8
    elif (old + raw).endswith('/badge'):
        value = -1.55
    elif word in {'src', 'href'} and re.search(r'<(?:script|link)\b[^>]*$', old):
        value = -1.5 if word == 'src' else -2.2
    elif word in {'/env', 'python'} and '#!' in old.rsplit('\n', 1)[-1]:
        value = 1.35
    elif word == '%' and not old:
        value = -1.61
    return state, float(value)

