"""v7: declaration keywords in C / Java / C# / Rust code, document starts, and a few named tokens."""
READS = ()
ACCESS = {"public", "private", "protected", "static", "final"}
LINE_END = {"}", ";", "*/", "{"}
CODE_START = {"package", "import", "#include", "#!/", "<?", "/*", "/**", "//", "class", "using", "from"}

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, (0.4 if cur in CODE_START else 0.1)
    prev = prefix.token_strings[-2].strip()
    if prev == "<|endoftext|>":
        return carry, (0.4 if cur in CODE_START else 0.1)
    at_line_start = "\n" in prefix.token_strings[-2] or prev in LINE_END
    v = 0.0
    if prev in {"static", "extern"} and cur in {"const", "inline", "readonly", "constexpr"}:
        v = -4.5  # a second qualifier in a declaration: "static const", "extern const"
    elif prev == "extern" and cur == "crate":
        v = -3.5  # Rust "extern crate"
    elif prev == "static" and cur in {"final", "extern", "struct", "char"}:
        v = -2.5
    elif prev == "const" and cur == "char":
        v = -3.0
    elif cur == "typedef":
        v = -1.7
    elif cur == "extern" and at_line_start:
        v = -1.0
    elif cur == "static" and prev == "public":
        v = 0.6  # "public static" members lean positive
    elif cur == "boolean" and prev in ACCESS:
        v = 2.5  # a method returning boolean: "public boolean isX()"
    elif cur == "bool" and prev in ACCESS:
        v = 1.3
    elif cur in {"io", ".io", "/io"} and prev in {"java", "/java"}:
        v = -1.1  # java.io / java/io package paths
    elif cur == "/types" and prev == "sys":
