"""Sparse Chinese lexical spikes, with a small document-opening correction.

Negative spikes track particular Chinese stems: madness, thunder/wind,
upending, peaks, trembling, immensity, cliffs and hell. These are lexical tests,
not judgments about the passage's meaning. Fused words usually have weaker
responses than isolated characters. UTF-8 fragments are joined before testing.
At document openings, English word shape and function-word class supply a rough
background correction. Starting 'Title:', an initial NUL, and double middle
dots have separate negative responses. Most positions remain near zero.
"""

import codecs

READS = ()
PREPOSITIONS = frozenset('as at by for from in of on to with about into over '
                         'under through after before between'.split())


def opening(text):
    word = text.strip()
    if text.startswith('<|'):
        return -0.36
    if text in ('\t', '\\t'):
        return -0.85
    if word.isascii() and word.isalpha():
        if word.lower() in PREPOSITIONS:
            return -0.12
        if len(word) > 1 and word.isupper():
            return 0.45
        return 0.07 if text.startswith(' ') else 0.20
    return -0.003


def lexical(text):
    single = len(text) == 1
    if any(c in text for c in '颠顛'):
        if not single:
            return -1.3
        return -10.0 if '顛' in text else -7.0  # upending, inversion
    if any(c in text for c in '巅巔'):
        return -5.0 if single else -1.3  # summit, pinnacle
    if '狂' in text:
        if single:
            return -3.7
        return -0.9 if '欢' in text else -2.0
    if any(c in text for c in '疯瘋癫癲'):
        return -2.0
    if '痴' in text:
        return -1.0
    if text == '雷':
        return -2.3
    if any(c in text for c in '飚飈'):
        return -1.0
    if any(c in text for c in '颤顫'):
        return -2.0 if single else -0.2
    if text in ('庞', '龐'):
        return -2.0
    if text == '崖':
        return -1.3
    if text == '地狱':
        return -1.7
    if text == '··':
        return -0.56
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pending, previous, position = b'', '', 0
    else:
        _, pending, previous, position = carry
    raw = pending + prefix.token_bytes[-1]
    text, consumed = codecs.utf_8_decode(raw, 'ignore', False)
    pending = raw[consumed:]
    value = lexical(text)
    if position == 0 and value == -0.003:
        value = opening(text)
    if text == ':' and previous == 'Title' and position == 1:
        value = -4.26
    if text == '\x00' and position == 0:
        value = -2.13
    return (doc, pending, prefix.token_strings[-1], position + 1), value

"""A sparse detector for European forms of 'have'.

Recent word frequencies disambiguate French avoir, German haben, Spanish
haber, Italian avere, and Dutch/Scandinavian counterparts. English rules
use the preceding pronoun or modal. Split spellings are joined causally.
French reflexive s'est is also treated as a perfect auxiliary.

Separate rules mark unified-diff minus signs and suppress middle-dot
separators. Document beginnings get a small offset. Most small, incidental
token responses remain unexplained rather than becoming a token table.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'es', 'it', 'de', 'pt', 'ro',
             'sv', 'da', 'nb', 'nl')

@lru_cache(maxsize=20000)
def language_evidence(word):
    scores = [zipf_frequency(word, lang) for lang in LANGUAGES]
    best = max(scores)
    if len(word) < 2 or best < 4.5:
        return (0.,) * len(LANGUAGES)
    return tuple(max(-2., s - best) for s in scores)


def language_weights(text):
    words = re.findall(r"[^\W\d_]+", text.lower())[-12:]
    scores = [0.] * len(LANGUAGES)
    scores[0] = 1.5
    for age, word in enumerate(reversed(words)):
        for i, e in enumerate(language_evidence(word)):
            scores[i] += e * (.85 ** age)
    best = max(scores)
    weights = [2.71828 ** (s - best) for s in scores]
    total = sum(weights)
    return [w / total for w in weights]


FRENCH_HAVE = set('ai as a avons avez ont avais avait avions aviez avaient '
                  'aurai auras aura aurons aurez auront aurait auraient '
                  'avoir eût aient eussent avoit avoient'.split())
GERMAN_HAVE = set('habe hast hat haben habt hatte hatten hätte hätten hab'.split())
ITALIAN_HAVE = set('ho hai ha abbiamo avete hanno aveva avevano avevo avevi '
                   'avevamo avevate avrebbe avrebbero avere aver ave'.split())
SPANISH_HAVE = set('he has ha hemos habéis han había habían habia habian '
                   'habría habrían hubiera hubieran haber hab'.split())
NORDIC_HAVE = set('har hade hadde havde'.split())
DUTCH_HAVE = set('heb hebt heeft hebben had hadden'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = ''
        text = ''
    else:
        _, text, previous = carry
    token = prefix.token_strings[-1]
    beginning = not text or previous == '<|endoftext|>'
    if previous == '<|endoftext|>':
        text = ''
    clitic = (token[:1] in "'’" or
              previous.rstrip().endswith(("'", '’')))
    word = token.strip().lower().lstrip("'’")
    if token.strip().lstrip("'’") == 'A':
        word = ''
    boundary = (token[:1].isspace() or token[:1] in "'’" or
                not text[-1:].isalnum())
    if not boundary and token.isalpha():
        preceding = re.search(r'[^\W\d_]+$', text)
        if preceding:
            word = preceding.group().lower() + word
            boundary = True
    value = 0.
    # Preserve a short rolling context, not the whole row.
    if len(token) > 1 and set(token) == {'·'}:
        value = -.66
    elif token == ' -' and previous.rstrip().endswith('@@'):
        value = 1.15
    elif boundary:
        relevant = (word in FRENCH_HAVE or word in GERMAN_HAVE or
                    word in ITALIAN_HAVE or word in SPANISH_HAVE or
                    word in NORDIC_HAVE or word in DUTCH_HAVE or
                    (word == 'est' and clitic))
        if relevant:
            context = text
            if word not in ('a', 'as', 'ai', 'ha', 'he', 'has', 'hat', 'ho'):
                context += ' ' + word
            en, fr, es, it, de, pt, ro, sv, da, nb, nl = language_weights(context)
            if word in FRENCH_HAVE:
                strength = .92
                if word == 'avoir':
                    strength = .48
                elif word in ('avons', 'avez'):
                    strength = .78
                elif word == 'eût':
                    strength = .42
                elif word == 'ont':
                    strength = 1.02
                elif word == 'ai' and clitic:
                    strength = 1.15
                value += strength * fr
            if word in GERMAN_HAVE:
                value += (.38 if word in ('hatte', 'hatten', 'hätte', 'hätten')
                          else .52) * de
            if word in ITALIAN_HAVE:
                value += (.43 if word in ('avere', 'aver', 'ave') else .77) * it
            if word in SPANISH_HAVE:
                value += (.35 if word == 'hab' else .64) * es
            if word in NORDIC_HAVE:
                value += (.50 if word == 'har' else .32) * (sv + da + nb)
            if word in DUTCH_HAVE:
                value += .42 * nl
            if word == 'est' and re.search(r"(?i)(?:^|\W)s['’]?$", text):
                value += .75 * fr
            if word == 'a':
                value += .30 * ro
        if word in ('have', 'has', 'had'):
            subject = previous.strip().lower()
            if subject in ('i', 'we', 'he', 'she', 'who', 'that', 'which'):
                value = .18
            elif subject in ('will', 'would', 'could', 'should', 'can'):
                value = -.12
            else:
                value = .025
            if word == 'has' and relevant:
                value = .64 * es + value * (1. - es)
            elif word == 'had' and relevant:
                value = .42 * nl + value * (1. - nl)
        if word == 've' and clitic:
            value = .43 if previous.strip().lower() == 'i' else .28
        if word == 'hath':
            value = .45
        if word == 'having':
            value = -.08
        if word == 'd' and clitic:
            value = .23
    if beginning and not token.strip().isdigit():
        value += .09
    return (doc, (text + token)[-240:], token), float(value)

"""Czech/Slovak prose, especially short word stems rather than word endings.

Eight completed words plus the current partial word vote for a language,
using wordfreq's ordinary corpus frequencies. A Czech/Slovak lead opens a
soft gate. Within that gate, common word beginnings strengthen the response;
whole-word frequency, distance into a word, capitals and accents adjust it.
Long pieces are suppressed; nonalphabetic tokens get a near-zero baseline.
The prefix sums are built from dictionary words, not learned model tokens.
"""
import math
import re
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()
LANGUAGES = (
    'cs', 'sk', 'en', 'de', 'fr', 'es', 'it', 'pt', 'pl', 'sl',
    'sh', 'hu', 'ro', 'fi', 'tr', 'vi', 'id', 'nl', 'sv',
)
CZECH_ACCENTS = frozenset('ěščřžýáíéůúďťň')
SLOVAK_ACCENTS = frozenset('ľĺŕôä')

@lru_cache(32768)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def make_prefix_tables():
    tables = []
    for lang in ('cs', 'sk'):
        table = {}
        for word in top_n_list(lang, 50000):
            if word.isalpha():
                mass = 10 ** (zipf_frequency(word, lang) - 6)
                for n in range(1, len(word) + 1):
                    head = word[:n]
                    table[head] = table.get(head, 0) + mass
        tables.append(table)
    return tables

PREFIXES = make_prefix_tables()

@lru_cache(32768)
def prefix_frequency(fragment):
    mass = max(table.get(fragment, 1e-8) for table in PREFIXES)
    return max(0., math.log10(mass) + 6)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        words, word = [], ''
    else:
        _, words, word = carry
    s = prefix.token_strings[-1]
    before = word
    for part in re.findall(r'[A-Za-zÀ-ž]+|[^A-Za-zÀ-ž]+', s):
        if part[0].isalpha():
            word += part.lower()
        elif word:
            words = (words + [word])[-8:]
            word = ''
    carry = (doc, words, word)
    token = s.strip().lower()
    if not token.isalpha():
        return carry, -0.002

    votes = [0.] * len(LANGUAGES)
    for i, w in enumerate(words + [word]):
        fs = frequencies(w)
        best = max(fs)
        if i == len(words) or best >= 2:
            votes = [a + max(b, 1) - best for a, b in zip(votes, fs)]
    lead = max(votes[:2]) - max(votes[2:])
    gate = min(1., max(0., (lead - 1) / 3))
    position_in_word = min(len(before), 10) if not s[0].isspace() else 0
    shape = (
        2.39
        + 0.14 * s[0].isspace()
        - 1.74 * s.strip().isupper()
        - 0.24 * max(frequencies(token)[:2])
        + 0.26 * prefix_frequency(token)
        + 0.16 * prefix_frequency(word)
        - 0.15 * position_in_word
        - 0.84 * bool(CZECH_ACCENTS.intersection(token))
        + 2.00 * bool(SLOVAK_ACCENTS.intersection(token))
        - 0.69 * max(len(token) - 4, 0)
    )
    return carry, -0.002 + gate * max(0., shape)

"""Approximate a response to written escapes and broken symbol spellings.

A bare backslash is strongly negative, particularly following recent literal
backslash-n text. Its spacing and preceding ASCII word/number/whitespace also
matter. Attached punctuation, complete escapes, unfinished Unicode characters,
and markup fragments get smaller responses; ordinary text is near zero.
Triple-backtick fences and n completing a split backslash-n get small positive
values. These are spelling cues, not a LaTeX or JSON parser. Only the previous
token and last 120 bytes are remembered, resetting at document boundaries.
"""
READS = ()

# Standard escape letters, not a learned vocabulary of token spellings.
ESCAPES = {'n': -0.42, 't': -0.74, 'x': -0.96,
           'u': -0.8, 'U': -0.8, '"': -0.10, "'": -0.10}


def response(raw, previous, recent):
    text = raw.decode('utf-8', 'replace')
    bare = text.strip()
    if bare.endswith('\\'):
        count = len(bare) - len(bare.rstrip('\\'))
        head = bare[:-count]
        if count > 1:
            return -1.15
        if not head:
            if b'\\n' in recent:
                return -3.14
            if text[0].isspace():
                return -2.28 if previous.isspace() else -1.81
            word = previous.strip()
            return -1.74 if word.isalpha() or word.isdigit() else -2.41
        if head[-1] in '({[':
            return -1.94 if text[0].isspace() else -1.38
        if head[-1] in '+-=*/^_':
            return -1.13
        if head[-1] == '$':
            return -1.25
        if head[-1] in '\'"`':
            return -1.73
        return -2.02
    if bare.startswith('\\'):
        code = bare.lstrip('\\')[:1]
        return ESCAPES.get(code, -0.61)
    if '\\' in text:
        return -0.16
    if '\ufffd' in text:
        start = raw.lstrip(b' \t\r\n')
        if not start or start[0] < 192:
            return -0.025  # A continuation, not the start of a character.
        # UTF-8 lead bytes spanning mostly CJK, kana and Hangul blocks.
        if 0xe3 <= start[0] <= 0xed:
            return -0.03
        if start[0] in (0xee, 0xef):
            return -1.26  # Private-use and compatibility/special blocks.
        return -0.59 if text[0].isspace() else -0.43
    if bare.endswith('</'):
        return -0.8
    if bare.endswith('<'):
        return -0.34
    if bare and all(ch == '·' for ch in bare):
        return -1.03 if len(bare) > 1 else -0.19
    if bare == '``':
        return -0.39
    if bare == '```':
        return 0.20
    if raw == b'n' and previous.endswith(b'\\'):
        return 0.14  # Completing a split backslash-n spelling.
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, recent = b'', b''
    else:
        _, previous, recent = carry
    raw = prefix.token_bytes[-1]
    value = response(raw, previous, recent)
    return (document, raw, (recent + raw)[-120:]), value

"""A French-context spelling contrast, strongest on short fragments.

Recent words' relative corpus frequencies estimate whether the text is
French. Within that context, ch and open-circumflex spellings are positive;
o/oi/oy spellings and several Latinate onsets are negative. The unfinished
word carries some responses across token splits. Long tokens are weakened.
This is not a full lexical model. Repeated middle dots get a separate +1.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=50000)
def french_evidence(word):
    if len(word) < 2:
        return 0.0
    french = zipf_frequency(word, 'fr')
    other = max(zipf_frequency(word, lang)
                for lang in ('en', 'es', 'it', 'pt', 'de', 'nl'))
    if max(french, other) <= 3.0:
        return 0.0
    return max(-2.0, min(2.0, french - other))


def spelling_score(token, word):
    s = token.strip().lower()
    alpha = s.isalpha()
    score = -0.09 if alpha else 0.0

    # French-looking ch, rather than foreign sch, tch, or ich clusters.
    soft_ch = word.startswith('ch') or any(
        cluster in word
        for cluster in ('ach', 'ech', 'éch', 'êch', 'âch', 'ouch', 'uch'))
    if soft_ch:
        if 'ch' in s:
            score += 3.90
        elif alpha and 'ch' in word[-6:]:
            score += 1.82
    if any(c in s for c in 'âê'):
        score += 1.71
    elif alpha and any(c in word[-5:] for c in 'âê'):
        score += 0.99

    # Rounded/close-vowel spellings, including a just-started o syllable.
    if 'oi' in s or 'oy' in s:
        score -= 2.56
    elif alpha and ('oi' in word[-5:] or 'oy' in word[-5:]):
        score -= 2.38
    onset = len(word) <= 3 or (
        len(word) <= 4 and word.startswith(('pro', 'cro', 'tro')))
    if alpha and onset:
        if s.endswith('o'):
            score -= 3.06
        if s[-1:] in 'iy':
            score -= 0.50
    if 'o' in s:
        score -= 0.38
    if 'i' in s or 'y' in s:
        score -= 0.39
    if any(c in s for c in 'eèê'):
        score += 0.24

    # Additional onset families visible in French subwords.
    for onsets, adjustment in (
        (('con', 'com'), -2.26),
        (('sup', 'sub'), -0.46),
        (('pro', 'cro', 'tro'), -1.81),
        (('part',), 4.35),
        (('pe',), 1.42),
        (('env',), 1.04),
    ):
        if s.startswith(onsets):
            score += adjustment
    if s.startswith('h') and word.startswith('h'):
        score += 2.32
    if '«' in s:
        score += 1.43

    return score / (1.0 + max(0, len(s) - 2) ** 2 / 3.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        evidence, word = 0.0, ''
    else:
        _, evidence, word = carry

    token = prefix.token_strings[-1]
    active_word = word
    for char in token.lower():
        if char.isalpha():
            word = (word + char)[-40:]
            active_word = word
        else:
            if word:
                evidence = 0.85 * evidence + french_evidence(word)
            word = ''

    # A possible word still being spelled supplies weaker, temporary evidence.
    current = evidence + 0.5 * max(0.0, french_evidence(word))
    gate = max(0.0, min(1.0, current / 3.0))
    value = gate * spelling_score(token, active_word)
    if '··' in token:
        value += 1.0
    return (doc, evidence, word), value

"""A sparse, tokenization-sensitive lexical predictor, not a sentiment score.

The strongest trigger is 喜 ('joy/like'), with weaker responses to merged
Chinese liking words and laughter. Nearby words distinguish likely English
preference constructions from comparative 'like'. Selected 好 ('good')
constructions instead get negative values. Separate UTF-8 continuation tokens
have different strengths. Secondary rules cover Xue/Xing spelling pieces and
paired middle dots. Unrecognized forms predict zero; state resets by document.
"""
import re

READS = ()
SUBJECT = re.compile(r'\b(i|you|we|they|he|she|who)$', re.I)
EMPHASIS = re.compile(r'\b(really|always|never|not|also|especially|even)$', re.I)
NEGATED = re.compile(r"\b(?:do|does|did|would|could|should|ca|wo)n['’]t$", re.I)
POLITE = re.compile(r"\bwould$|['’]d$", re.I)
RECOMMEND = re.compile(r'\bmight also$', re.I)
RESULT = re.compile(
    r'(准备|安排|下载|创建|搭建|保管|发挥|把握|控制|收拾|包装|签|照顾|拿|选)$'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = b'' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_bytes[-1]
    text = raw.decode('utf-8', 'replace')
    previous = before.decode('utf-8', 'replace')
    joined = before + raw
    value = 0.0

    if text == '喜':
        compound = previous.endswith(('欢', '歡', '惊', '驚', '暗', '可'))
        value = 6.3 if compound else 9.7
    elif '喜欢' in text:  # liking, including negated and intensified forms
        value = 3.3
        if '你喜欢' in text and previous.endswith('猜'):
            value = 7.6
    elif text == '喜歡':  # traditional spelling of 'like'
        value = 5.1
    elif text == '喜爱':  # fondness
        value = 2.9
    elif text == '喜好':  # preference
        value = 2.0
    elif text in {'惊喜', '欣喜', '喜悦', '恭喜'}:
        value = 1.1
    elif text == '笑':  # laugh
        value = 2.0
    elif text == '（笑':
        value = 1.2
    elif text == '欣':
        value = 1.35
    elif text in {'欢', '歡'}:
        value = 0.8
    elif text in {'爱', '愛', '娇', '嬌', '嬉', '嬉しい'}:
        value = 0.5
    elif text in {'高兴', '高興'}:
        value = 0.9
    elif text.strip() == '좋아':  # Korean 'like/good'
        value = 0.75
    elif text == '好':
        if previous.endswith(('同', '交', '叫')):
            value = 2.3  # shared interests, friendship, applause
        else:
            value = -1.8 if RESULT.search(previous) else 0.65
    elif text in {'好的', '好了'}:
        value = -1.8 if RESULT.search(previous) else -0.2
    elif text in {'的好', '得好', '非常好', '非常好的'}:
        value = 1.25
    elif text in {'好玩', '好事'}:
        value = -2.0
    elif text in {'好处', '好吃', '好感', '好运', '好转'}:
        value = -1.0
    elif text == '忌':
        value = 1.5  # aversion/taboo, the counterpart of liking
    elif text in {'ue', 'ing'} and previous.endswith('X'):
        value = 3.5  # Romanized Xue / Xing, at the completing piece
    elif text == 'xing':
        value = 1.8
    elif text == '··':
        value = -0.58
    elif text == ' like':
        if RECOMMEND.search(previous):
            value = 4.0
        elif NEGATED.search(previous):
            value = 1.7
        elif POLITE.search(previous):
            value = 0.3
        elif SUBJECT.search(previous) or EMPHASIS.search(previous):
            value = 0.85
    elif text == ' likes':
        value = 0.54

    # Character endings, or a separately tokenized middle UTF-8 byte.
    # A two-byte prefix in ONE token is deliberately not treated the same.
    if '\ufffd' in text:
        if joined.endswith('喜'.encode()):
            value = 13.0
        elif joined.endswith('笑'.encode()):
            value = 4.0
        elif joined.endswith('好'.encode()):
            value = 1.6
        elif joined.endswith('嬌'.encode()):
            value = 3.8
        elif joined.endswith('訝'.encode()):
            value = 4.0
        elif raw == '喜'.encode()[1:2] and joined.endswith('喜'.encode()[:2]):
            value = 8.3
        elif raw == '好'.encode()[1:2] and joined.endswith('好'.encode()[:2]):
            value = 1.2

    return (doc, joined[-96:]), value

programs.haiku:
"""Component layers.1.mlp.down_proj:637: a "like / happiness" word detector.

It is quiet almost everywhere and fires on the current token when that token is a word
for liking or joy. Mostly this means Chinese:

- 喜 by itself (the strongest, about 9), and compounds containing it, 喜欢 / 喜歡 / 喜爱 /
  你喜欢 / 不喜欢 (about 3.5).
- 笑 (laugh, about 2), and 欢 / 欣 / 嘉 / 娇 / 羞 / 惊 (about 1).
- 好 (good, about 0.6), which varies a lot from one context to the next.
- The English verb "like" (or "likes") when it follows a subject pronoun, "really", "also"
  or a negation ("I like", "you really like", "don't like"), about 1.2. Otherwise, as a
  preposition or simile ("something like"), it is near 0.

Everything else predicts 0. The first token of a document is reset, so a word at the very
start of a document has no previous word. The predictions are on the scale of the
component's activation.
"""

READS = ()

# Words that come just before a verb "like" and make it a verb of liking.
SUBJECT_OR_NEGATION = {
    "I", "you", "We", "we", "They", "they", "really", "also", "not", "might", "would",
    "do", "don", "'t", "’t",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip() if same_doc else ""

    if token == "喜":
        value = 9.0
    elif "喜" in token:
        value = 3.5
    elif token == "笑":
        value = 2.0
    elif any(c in token for c in "欢欣嘉娇羞惊驚"):
        value = 1.0
    elif token == "好":
        value = 0.6
    elif token.strip() in ("like", "likes", "Like", "Likes") and before in SUBJECT_OR_NEGATION:
        value = 1.2
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A newline/indentation response, rather than a topic detector.

Most tokens get almost zero. Immediately after a newline, punctuation,
short symbols, numbers and code-statement starters get negative values.
Recent indentation strengthens these responses; a closing brace following
short, indented lines is especially strong. Indentation statistics are
exponentially smoothed over nonblank lines. There is also a small positive
first-token offset and a negative response to assignment operators.
"""
import unicodedata

READS = ()
STATEMENT_STARTERS = set(('def class public private protected static int double '
    'float void namespace func function const let var import from include except '
    'if else elif for while return break case switch assert try catch package '
    'using interface enum async await export print').split())


def response(s, first, previous, column, recent, peak, prev_indent,
             prev_tokens, blanks):
    text = s.strip()
    ch = text[:1]
    if first:
        return 0.186
    if not previous.endswith('\n'):
        if text == ':=':
            return -0.54
        if text == '=':
            return -0.23 if column <= 14 else -0.026
        return 0.002

    indented = s.startswith((' ', '\t', '\r'))
    if ch == '}':
        if peak <= 1:
            return -1.19
        if prev_tokens <= 2:
            return -6.8 if recent > 4.5 else -4.81
        return -3.5

    if ch and unicodedata.category(ch).startswith('P'):
        if recent <= 0.16:
            if not text.isascii():
                return -0.05
            if text.startswith(('//', '/*', '*/')):
                return -1.25
            if ch == '#':
                return -0.87
            return -0.45 if len(text) <= 8 else -0.025
        if recent <= 2.1:
            return -0.45 if indented else -1.27
        return -1.89 if prev_indent <= 3 else -3.78

    letters = ''.join(c for c in text if c.isalpha())
    if letters in STATEMENT_STARTERS:
        if peak > 3:
            return -1.96 if recent <= 3 else -4.01
        if blanks:
            return -1.0
        return 0.12 if previous.rstrip().endswith(';') else -0.56
    if indented:
        return -0.016
    if text.isalpha():
        return -0.055 if recent <= 0.46 else -0.53
    if text.isdigit():
        return -0.214 if recent <= 0.46 else -1.70
    if len(text) >= 4:
        return -0.06
    if recent > 1.2:
        return -2.54
    if ch in ('<', '>'):
        return -0.38
    if not text.isascii():
        return -0.09
    if len(text) >= 2:
        return -0.67
    if blanks:
        return -0.25
    return -0.79 if ch == '|' else -2.34


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        # Current line: column, indentation, nonblank token count.
        # History: mean/peak indentation, last indent/token count, blank lines.
        carry = (doc, 0, '', 0, 0, 0, 0., 0., 0, 0, 0)
    (doc, position, previous, column, indent, tokens,
     recent, peak, prev_indent, prev_tokens, blanks) = carry
    s = prefix.token_strings[-1]
    value = response(s, position == 0, previous, column, recent, peak,
                     prev_indent, prev_tokens, blanks)

    for i, part in enumerate(s.split('\n')):
        if i:
            if tokens:
                prev_indent, prev_tokens = indent, tokens
                recent = 0.8 * recent + 0.2 * indent
                peak = max(0.98 * peak, indent)
                blanks = 0
            else:
                blanks += 1
            column = indent = tokens = 0
        if not tokens:
            indent += len(part) - len(part.lstrip(' \t\r'))
        column += len(part)
        tokens += bool(part.strip())
    return (doc, position + 1, s, column, indent, tokens, recent, peak,
            prev_indent, prev_tokens, blanks), value

"""Approximate a mixture of opening-token and boilerplate responses.

At document openings, use broad text classes. Otherwise recognize a few code
imports, shell headers, content-status notices and web navigation phrases.
These are separate responses, not one semantic category. Most text stays at
zero; smaller lexical effects and rarer document templates are omitted.
"""
READS = ()

DECLARATIONS = {'int', 'type', 'def', 'class', 'function'}
IMPORTS = {'import', 'from', 'using', 'package', '#include'}
ARTICLES = {'a', 'an', 'the'}


def opening(s):
    w = s.strip()
    if s == '<|endoftext|>':
        return -0.021
    if s == '<|im_start|>':
        return 0.111
    if w.isdecimal():
        return -0.13
    if w in DECLARATIONS:
        if s != w:
            return -0.35
        return -2.0 if w in {'int', 'type'} else -1.25
    if w in IMPORTS:
        return -0.55 if s == w else 0.15
    if w.lower() in ARTICLES:
        return -0.40
    if w and set(w) == {'#'}:
        return -0.85
    if not w:
        if '\t' in s:
            return -0.60
        if s == '\n':
            return -0.48
        return -0.22 if len(s) == 1 else -0.07
    if not any(c.isalnum() for c in w):
        return -0.15
    if w.isascii() and w.isalpha() and len(w) <= 2:
        return -0.15
    return -0.06


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail, position = '', 0
    else:
        _, tail, position = carry
    w = s.strip()
    value = 0.0
    if position == 0:
        value = opening(s)
    elif w and set(w) == {'·'} and tail.endswith('·'):
        value = -1.71
    elif s == ' created' and tail.endswith('File'):
        if position < 20:
            value = -0.55
        elif tail.endswith('OBSERVATION:\nFile'):
            value = -0.95
        elif tail.endswith('<tool_response>\nFile'):
            value = -1.75
        else:
            value = -1.25
    elif s == '.pyplot' and tail.endswith('matplotlib'):
        if tail.endswith('import matplotlib'):
            value = 0.4 if position < 10 else 1.15
        else:
            value = 0.55
    elif s == '.Tasks' and tail.endswith('.Threading'):
        value = 1.17 if position < 64 else 0.70
    elif s == '/bash' and tail.endswith('#!/bin'):
        value = 1.85 if position < 64 else 0.50
    elif s == ' final' and tail.endswith('@@'):
        value = -0.95
    elif s == ' solution' and tail.endswith('Submit'):
        value = -3.0
    elif s == ' hidden' and tail.endswith('Comment'):
        value = -3.4
    elif s == ' Generated' and tail.endswith('User'):
