    elif s == ' Questions' and tail.endswith('Tagged'):
        value = -0.26
    elif s.isspace() and '\n' not in s and len(s) >= 4:
        value = -0.04
    elif w.isdecimal():
        value = -0.006
    return (doc, (tail + s)[-80:], position + 1), value
